AWARDS_MCQS = [
    # ── Nobel Prizes 2025 (23001-23012) ──
    {"id":23001,"question_text":"The Nobel Prize in Physics 2025 was awarded for which discovery foundational to quantum computing?","option_a":"Detection of gravitational waves using LIGO","option_b":"Macroscopic quantum mechanical tunnelling and energy quantisation in electric circuits","option_c":"Observation of the Higgs boson at CERN","option_d":"Development of attosecond pulses","correct_answer":"B","explanation":"Nobel Physics 2025: John Clarke, Michel H. Devoret, and John M. Martinis — for macroscopic quantum mechanical tunnelling and energy quantisation in electric circuits. This foundational work enabled superconducting qubit-based quantum computers, the most practical approach to quantum computing today. Martinis led Google's quantum team that achieved 'quantum supremacy' in 2019 using the Sycamore processor — performing calculations in 200 seconds that would take classical computers ~10,000 years. This award reflects the global race in quantum computing where nations like India are investing heavily (IIT Delhi, CSIR labs launching quantum research centres by 2026). The 2025 Physics Nobel underscores how quantum technology will shape 21st-century computing globally. Nobel Physics 2024: Hopfield & Hinton (AI/neural networks).","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23002,"question_text":"Nobel Prize in Chemistry 2025 was awarded for the development of which ultra-porous crystalline materials?","option_a":"Graphene nanoribbons","option_b":"Metal-organic frameworks (MOFs)","option_c":"Zeolite catalysts","option_d":"Carbon nanotubes","correct_answer":"B","explanation":"Nobel Chemistry 2025: Susumu Kitagawa, Richard Robson, and Omar M. Yaghi — for developing metal-organic frameworks (MOFs). MOFs represent a breakthrough in materials science with the highest surface area per gram of any known material (~7,000 m²/g — larger than a football field in a single gram). Applications span critical global challenges: CO2 capture for climate action, hydrogen storage for clean fuel cells, water harvesting from desert air (particularly relevant for India's water security challenges), medical drug delivery, and environmental remediation. Omar Yaghi (UC Berkeley, Syrian-American) coined 'reticular chemistry' — the science of linking molecular building blocks into extended frameworks. India's Institute of Technology Delhi (IIT Delhi) and other research centres are developing MOF applications for air purification and water treatment in urban areas. This chemistry award exemplifies how fundamental science drives solutions to planetary challenges. Yaghi's work bridges continents — Kitagawa (Kyoto University, Japan) and Robson (University of Melbourne, Australia) represent Asia-Pacific's role in materials science.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23003,"question_text":"Nobel Prize in Physiology/Medicine 2025 was awarded for the discovery of which immune cells that prevent autoimmune diseases?","option_a":"Natural killer (NK) cells","option_b":"Dendritic cells","option_c":"Regulatory T cells (Tregs)","option_d":"B lymphocytes","correct_answer":"C","explanation":"Nobel Medicine 2025: Mary E. Brunkow, Fred Ramsdell, and Shimon Sakaguchi — for discovering regulatory T cells (Tregs) and their critical role in preventing autoimmune diseases. Tregs express the FOXP3 transcription factor and act as 'immune brakes' to prevent the body's immune system from attacking its own tissues. Mutations in FOXP3 cause IPEX (Immune dysregulation, Polyendocrinopathy, Enteropathy, X-linked) syndrome — a severe condition. This discovery opened new therapeutic avenues for treating autoimmune diseases (rheumatoid arthritis, lupus, Type 1 diabetes) — significant health concerns in India affecting millions. Treg-targeted therapies are now in clinical trials globally. Sakaguchi's work (Osaka University) demonstrated that depleting Tregs leads to autoimmunity, while boosting Tregs prevents it. This Nobel recognises how fundamental immunology discoveries translate to treating chronic inflammatory conditions. The recognition also highlights Japan's leadership in immunology research alongside American and international contributions. Nobel Medicine 2024: Ambros & Ruvkun (microRNA discovery in gene regulation).","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23004,"question_text":"Which Hungarian author won the Nobel Prize in Literature 2025 for 'compelling and visionary oeuvre that reaffirms the power of art amid apocalyptic terror'?","option_a":"Péter Nádas","option_b":"Imre Kertész","option_c":"László Krasznahorkai","option_d":"György Konrád","correct_answer":"C","explanation":"Nobel Literature 2025: László Krasznahorkai (Hungary) — for his 'compelling and visionary oeuvre that, in the midst of apocalyptic terror, reaffirms the power of art.' His masterpiece 'Satantango' (1985) uses innovative 12-chapter structure mimicking Argentine tango (6 steps forward + 6 back), set in a decaying Hungarian collective farm post-communism. The novel explores despair, salvation, and human ambition through long, hypnotic prose. Director Béla Tarr adapted it into a monumental 7.5-hour film (1994) considered one of cinema's greatest achievements. Krasznahorkai's work reflects Central European existential philosophy — themes of state collapse, individual powerlessness, and art's redemptive potential resonate globally. His 2025 Nobel recognition celebrates Hungarian literature's global significance alongside the same year's Booker Prize winner David Szalay (Hungarian-British), making 2025 a banner year for Hungarian letters. Krasznahorkai's themes of institutional breakdown and moral uncertainty are studied in universities worldwide, influencing contemporary writers beyond Europe. His recognition affirms how Eastern European voices challenge Western literary dominance. Nobel Literature 2024: Han Kang (South Korea, first Korean to win).","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23005,"question_text":"The Nobel Peace Prize 2025 was awarded to Maria Corina Machado for her democratic struggle in which country?","option_a":"Cuba","option_b":"Nicaragua","option_c":"Bolivia","option_d":"Venezuela","correct_answer":"D","explanation":"Nobel Peace Prize 2025: Maria Corina Machado (Venezuela) — for 'tireless work promoting democratic rights for the people of Venezuela and her struggle to achieve a just and peaceful transition from dictatorship to democracy.' Machado is the face of Venezuelan opposition against Nicolás Maduro's 25-year authoritarian rule. Despite winning the 2024 opposition presidential primary with overwhelming support, she was barred from candidacy by Maduro's regime using arbitrary legal disqualifications — a hallmark of autocratic suppression. She continues leading her 'Vente Venezuela' movement from exile while maintaining communications with supporters inside the country. Venezuela's humanitarian crisis has displaced over 7.7 million refugees globally, including to India and other South Asian nations. The Nobel award recognises her non-violent resistance and commitment to restoring democratic institutions. Her struggle exemplifies global democracy defenders facing authoritarian oppression — similar to contemporary challenges in Myanmar, Iran, and elsewhere. The award validates civil society resistance and international solidarity with democratic movements. Nobel Peace Prize 2024: Nihon Hidankyo (Japanese atomic bomb survivors advocacy). Nobel Peace Prize 2023: Narges Mohammadi (Iran's women's rights, jailed).","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23006,"question_text":"Nobel Prize in Economic Sciences 2025 was awarded for research on innovation-driven growth and 'creative destruction.' Who were the laureates?","option_a":"Daron Acemoglu, Simon Johnson, James Robinson","option_b":"Claudia Goldin, Lawrence Katz, Lawrence Summers","option_c":"Joel Mokyr, Philippe Aghion, Peter Howitt","option_d":"Paul Romer, Robert Lucas, Robert Barro","correct_answer":"C","explanation":"Nobel Economics 2025: Joel Mokyr, Philippe Aghion, and Peter Howitt — for explaining how technological innovation drives long-term economic growth. Mokyr (Northwestern University) conducted historical analysis tracing technological breakthroughs and institutional conditions enabling innovation across centuries — showing how the Industrial Revolution emerged from specific social structures. Aghion & Howitt developed 'endogenous growth' theory with 'creative destruction' — new innovations render older products/technologies obsolete while creating new markets and employment, driving sustained GDP growth. This framework explains why countries investing in R&D (like India's increasing CSIR and startup ecosystem investments) experience higher long-term productivity. The award underscores innovation's centrality to development economics — relevant to India's tech startup boom, IT services sector, and emerging manufacturing. Their work validates public investment in education and research infrastructure as drivers of prosperity. Nobel Economics 2024: Acemoglu, Johnson, Robinson (institutions & prosperity). The 2025 award celebrates how innovation systems shape national development trajectories.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23007,"question_text":"Nobel Chemistry 2025 laureate Omar M. Yaghi is known as the father of which branch of chemistry?","option_a":"Green chemistry","option_b":"Reticular chemistry","option_c":"Electrochemistry","option_d":"Supramolecular chemistry","correct_answer":"B","explanation":"Omar M. Yaghi (UC Berkeley) pioneered and named 'reticular chemistry' — the science of linking organic and inorganic molecular building blocks (linkers and nodes) into extended crystalline porous frameworks via strong chemical bonds. This controlled-architecture approach creates materials with unprecedented properties. His metal-organic frameworks (MOFs) can hold 200 times more hydrogen than steel cylinders at identical pressure — critical for hydrogen fuel storage in vehicles. Yaghi's reticular chemistry has enabled MOFs to capture CO2 from industrial emissions and even directly from ambient air — urgent climate change applications. His work demonstrates how fundamental chemistry discoveries translate to solving global challenges. Yaghi's Nobel win (shared with Kitagawa, Kyoto University; Robson, University of Melbourne) represents international scientific collaboration. The award recognises how 'molecular engineering' creates designer materials with precisely controlled pore sizes, chemical affinities, and functionalities for applications from water purification to pharmaceutical manufacturing. His recognition elevates reticular chemistry as a defining 21st-century materials science field. The 2025 Chemistry Nobel celebrates how human-designed porous materials outperform nature in specific applications.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23008,"question_text":"László Krasznahorkai's Nobel-winning novel 'Satantango' has a unique structure. What is distinctive about its 12 chapters?","option_a":"Written entirely in one sentence","option_b":"6 forward + 6 backward chapters mimicking tango steps","option_c":"12 chapters each told by a different character","option_d":"Alternates between past and future timelines","correct_answer":"B","explanation":"Krasznahorkai's 'Satantango' (1985) features an ingenious structural mirror: 12 chapters composed as 6 forward + 6 backward — directly mirroring the Argentine tango's choreographic pattern of six steps forward followed by six steps backward. This structural parallelism between dance movement and narrative structure creates a unique reading experience — the second half reverses and recontextualises earlier scenes. Set in a decaying Hungarian collective farm in the post-communist 1980s, the novel captures societal collapse, moral corruption, and individual desperation through this dance-like narrative rhythm. Director Béla Tarr's acclaimed film adaptation (1994) stretches to 7.5 hours, becoming a cinema landmark through its static camera shots and deliberate pacing that mirrors the novel's meditative density. The tango structure symbolises how history repeats in cycles — forward progress inevitably followed by retreat, mirroring Hungary's 20th-century oscillations between authoritarian regimes. Krasznahorkai's formal innovation demonstrates how narrative structure embodies philosophical content — a signature of contemporary literary excellence. The Nobel Literature 2025 recognition affirmed how Eastern European experimental fiction challenges conventional storytelling globally. The novel's structure influenced contemporary authors exploring cyclical and non-linear narratives.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23009,"question_text":"The Nobel Peace Prize is uniquely awarded in which city, unlike the other Nobel Prizes given in Stockholm?","option_a":"Brussels, Belgium","option_b":"Oslo, Norway","option_c":"Copenhagen, Denmark","option_d":"Helsinki, Finland","correct_answer":"B","explanation":"The Nobel Peace Prize is uniquely awarded in Oslo, Norway by the Norwegian Nobel Committee — the only Nobel Prize distinguished by its geographic separation. All other Nobel Prizes (Physics, Chemistry, Medicine/Physiology, Literature, Economics) are awarded in Stockholm, Sweden by Swedish institutions. This geopolitical distinction reflects Alfred Nobel's 1895 will and his deliberate choice to award peace separately through Norwegian governance — reflecting Scandinavia's historical commitment to arbitration and conflict resolution. The ceremony at Oslo's Oslo City Hall represents Norway's soft power projection and emphasises that peace-making is a distinct endeavour from scientific/literary achievement. Recipients are invited to deliver the Nobel Peace Lecture — a global platform amplifying their causes and message. The Oslo setting symbolises Scandinavian neutrality and international cooperation. This institutional separation has given the Peace Prize unique gravitas and symbolic weight in international diplomacy. Nobel Peace 2025: Maria Corina Machado (Venezuela, democratic opposition). Nobel Peace 2024: Nihon Hidankyo (Japanese atomic bomb survivors' peace advocacy). India has produced Peace Prize winners: Kailash Satyarthi (2014, child labour), Rabindranath Tagore (1913, poet/philosopher), Motilal Nehru and Gandhi (nominated multiple times, Gandhi controversially never won). The Peace Prize's Oslo location emphasises universal values transcending national boundaries.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23010,"question_text":"Nobel Physics 2025 laureate John M. Martinis led which tech company's team to claim 'quantum supremacy' in 2019?","option_a":"IBM","option_b":"Microsoft","option_c":"Google","option_d":"Intel","correct_answer":"C","explanation":"John M. Martinis led Google's quantum computing division whose Sycamore processor claimed 'quantum supremacy' in 2019 — a watershed moment when a quantum computer performed a specific calculation in 200 seconds that leading classical supercomputers would require ~10,000 years to solve. This demonstrated quantum computing's potential advantage over classical computing for certain problem classes. Martinis' foundational work on superconducting qubits (quantum bits) and their energy quantisation made this breakthrough possible. His Nobel Physics 2025 recognition (shared with John Clarke and Michel H. Devoret) honours the theoretical underpinnings enabling practical quantum computers. Superconducting qubits operate at near absolute zero (millikelvins), exploiting quantum tunnelling — particles passing through energy barriers classically forbidden. This quantum advantage has profound implications for cryptography, drug discovery, materials science, and optimisation problems. India is rapidly building quantum computing capabilities (IIT Delhi, Tata Institute of Fundamental Research launching quantum centres) recognising that quantum technology will reshape global computing and cybersecurity. Google's quantum leadership represents American tech dominance in next-generation computing, while other nations (China with Jiuzhang, IBM with quantum services) pursue parallel approaches. The 2025 Physics Nobel affirms quantum computing's transition from theoretical physics to practical engineering.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23011,"question_text":"Metal-organic frameworks (MOFs) — subject of Nobel Chemistry 2025 — are being tested for which crucial climate application?","option_a":"Ocean plastic degradation","option_b":"Nuclear waste disposal","option_c":"Carbon dioxide capture and storage","option_d":"Soil decontamination","correct_answer":"C","explanation":"Metal-organic frameworks (MOFs), honoured in Nobel Chemistry 2025, represent a transformative solution for CO2 capture — a critical climate change mitigation technology. MOFs' exceptional properties make them ideal for this application: their ultra-high surface area (up to 7,000 m²/g, equivalent to an American football field compressed into a gram) can adsorb vast amounts of CO2 from industrial flue gases and directly from ambient air. Point-source capture (factory emissions) and direct air capture (DAC) are both viable pathways. Several MOF-based CO2 capture systems are transitioning from laboratories to pilot plants worldwide. Beyond climate applications, MOFs excel in complementary challenges: water harvesting from desert and arid air (relevant to India's water security in drought-prone regions), hydrogen storage for clean fuel cells in transport decarbonisation, pharmaceutical drug delivery optimising bioavailability, and environmental remediation of contaminated water. The 2025 Nobel Chemistry recognition validates MOFs as foundational to climate solutions. India's CSIR laboratories are exploring MOF applications for air purification and water treatment in urban areas. The award signifies how fundamental materials science directly addresses planetary challenges — climate change, water scarcity, energy transition. MOF technologies represent humanity's technological response to existential environmental threats.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23012,"question_text":"The 2025 Nobel Prize in Economic Sciences was the Sveriges Riksbank Prize. How does it differ from the original Nobel Prizes?","option_a":"It is awarded only to European economists","option_b":"It was established in 1968 in memory of Alfred Nobel, not part of original 1895 will","option_c":"It carries no monetary prize","option_d":"It is awarded every two years","correct_answer":"B","explanation":"The Nobel Prize in Economic Sciences (formally 'Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel') was established in 1968 by Sweden's Riksbank (central bank) — significantly, it was NOT part of Alfred Nobel's original 1895 will. The original five Nobel Prizes (Physics, Chemistry, Medicine/Physiology, Literature, Peace) were endowed by Alfred Nobel's testament. The Economics Prize was added later, reflecting 20th-century recognition of economics' importance to human society. The first Economics Prize was awarded in 1969 to Ragnar Frisch (Norway) and Jan Tinbergen (Netherlands) for developing econometric models. By 2025, the Economics Prize carries equal prestige and monetary value (~10 million SEK) as other Nobels, though technically it remains a separate institution. This historical distinction highlights how awards evolve to reflect changing disciplinary prominence. India has produced Economics laureates: Amartya Sen (1998, development economics and poverty), Abhijit Banerjee (2019, poverty alleviation), and Esther Duflo (2019 co-winner, from MIT). The 2025 Economics Prize honouring Joel Mokyr, Philippe Aghion, and Peter Howitt recognised innovation-driven growth — relevant to India's development trajectory and STEM innovation investment. The prize's evolution demonstrates how international recognition adapts to emerging knowledge domains.","folder":"AP_HC","topic":"International_Current_Affairs"},

    # ── Grammys 67th — February 2025 (23013-23017) ──
    {"id":23013,"question_text":"Beyoncé won Album of the Year at the 67th Grammy Awards (February 2025) for which album — her first ever AOTY win?","option_a":"Renaissance","option_b":"Cowboy Carter","option_c":"Lemonade","option_d":"4","correct_answer":"B","explanation":"67th Grammy Awards (February 2, 2025, Crypto.com Arena, Los Angeles): Beyoncé achieved a long-overdue milestone winning Album of the Year for 'Cowboy Carter' — a country-crossover album and her FIRST Grammy Album of the Year award despite receiving a record number of nominations throughout her career. The win ended decades of speculation about whether the Grammys would finally give her the industry's highest honour. She also won Best Country Album and Best Country Duo/Group Performance, cementing her crossover into country music. 'Cowboy Carter' (2024) represents Beyoncé's artistic evolution, drawing on country music traditions often historically excluded from by African American artists. The album reclaims country music heritage and includes production innovation. This win carried cultural significance beyond music — recognition of Black artists in traditionally white-dominated country genre. The ceremony was delayed one day (from Feb 1) due to devastating Los Angeles wildfires of January 2025, showcasing the event's adaptability during crises. Beyoncé holds the all-time record for most Grammy nominations by any artist (32+ nominations). Her AOTY win validated decades of creative excellence and cultural impact. The award demonstrated Grammy recognition evolving toward historic correction — acknowledging overlooked achievements by one of music's greatest artists.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23014,"question_text":"Kendrick Lamar won 5 out of 5 nominations at the 67th Grammys 2025, sweeping with which diss track targeting Drake?","option_a":"Euphoria","option_b":"Meet the Grahams","option_c":"Not Like Us","option_d":"6:16 in LA","correct_answer":"C","explanation":"67th Grammy Awards (February 2025): Kendrick Lamar executed a historic clean sweep, winning ALL 5 nominations with 'Not Like Us' — a diss track in the highly publicised rap feud targeting Drake. The five Grammy wins were: Record of the Year, Song of the Year, Best Rap Song, Best Rap Performance, and Best Music Video. This perfect sweep demonstrated critical and commercial validation of Lamar's artistry and competitive prowess in hip-hop. 'Not Like Us' became a cultural phenomenon and streaming mega-hit, dominating charts globally. Lamar's Grammy dominance reflected his standing as hip-hop's preeminent artist of the 2020s. He subsequently performed 'Not Like Us' at the Super Bowl LIX halftime show (February 9, 2025) in New Orleans — amplifying the track before a 100+ million global audience. Serena Williams appeared in the halftime audience, underscoring celebrity-calibre draw. Kendrick Lamar represents Compton, California's artistic legacy, continuing traditions of West Coast hip-hop excellence. The 67th Grammys confirmed his status surpassing contemporary rivals. His sweep exemplified how hip-hop has become the Grammy Awards' dominant force — culturally defining popular music. Lamar's February 2025 dominance positioned him for further Grammy milestones at subsequent ceremonies.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23015,"question_text":"Who won Best New Artist at the 67th Grammy Awards 2025?","option_a":"Sabrina Carpenter","option_b":"Chappell Roan","option_c":"Gracie Abrams","option_d":"Teddy Swims","correct_answer":"B","explanation":"67th Grammy Awards (February 2025): Best New Artist: Chappell Roan — a breakthrough artist who emerged as 2024's most explosive newcomer. Known for the viral hit 'Good Luck, Babe!' and her debut album 'The Rise and Fall of a Midwest Princess' (2023), Roan represents a new generation of LGBTQ+ pop artists with uncompromising authenticity. Her song 'Good Luck, Babe!' became a global streaming phenomenon and anthem for queer communities. Roan delivered a memorable acceptance speech addressing artist rights, mental health, and the pressures of sudden fame. At age 26, she becomes the first artist of her demographic to win Best New Artist at the 67th Grammys. The award validates her as a generational voice in pop music and LGBTQ+ representation in mainstream awards. Chappell Roan's win marks continued diversification of Grammy's Best New Artist category — recognising artists beyond traditional pop/hip-hop crossover appeal. Her meteoric rise exemplifies social media's role in building contemporary music audiences (TikTok initially amplified 'Good Luck, Babe!'). Roan represents American pop music's evolution toward inclusive representation. Her 2025 Grammy win positioned her for sustained influence shaping pop music and LGBTQ+ cultural visibility in mainstream entertainment awards.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23016,"question_text":"Beyoncé's 'Cowboy Carter' at the 67th Grammys 2025 was notable as she became the first Black woman to win Grammy for Best Country Album. What record does she hold overall?","option_a":"First woman to win Record of Year 3 times","option_b":"Most Grammy wins by any artist (32 wins)","option_c":"Only artist to win all 4 General Field categories","option_d":"First artist to win Album of Year 4 times","correct_answer":"B","explanation":"Beyoncé holds the all-time record for most Grammy wins by any artist — 32 Grammy Awards (as of February 2025). She surpassed conductor Georg Solti's previous record of 31 Grammys. Her 'Cowboy Carter' Album of the Year win was her FIRST in that prestigious General Field category despite a remarkable string of 9 previous nominations in this category spanning decades. The long delay before her AOTY win sparked Grammy accountability conversations about recognition gaps for Black artists and women in music's highest honours. Beyoncé's 32 Grammy wins span multiple decades and genres — pop, R&B, hip-hop collaborations, live performances, and country crossover. Her historic milestone reflects unparalleled creative output, commercial success, and artistic innovation. The 67th Grammy Awards (February 2, 2025) held at Crypto.com Arena in Los Angeles featured Beyoncé as the night's dominant winner and cultural centre. Her record 32 Grammys position her as the most-awarded artist in Grammy history — a distinction likely to stand for decades. The achievement validates her legacy as music's greatest contemporary artist and demonstrates how Grammy recognition, when applied fairly, can honour transformative talent. Beyoncé's Grammy milestone represents American music industry's evolution toward recognising excellence across racial and gender lines.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23017,"question_text":"Kendrick Lamar performed 'Not Like Us' at the Super Bowl LIX halftime show in February 2025. Where was Super Bowl LIX held?","option_a":"Las Vegas, Nevada","option_b":"New Orleans, Louisiana","option_c":"Los Angeles, California","option_d":"Miami, Florida","correct_answer":"B","explanation":"Super Bowl LIX (February 9, 2025) was held at the Caesars Superdome in New Orleans, Louisiana — with the Philadelphia Eagles defeating the Kansas City Chiefs 40-22 in a thrilling matchup. Kendrick Lamar headlined the Super Bowl LIX halftime show, performing 'Not Like Us' to over 100 million global viewers — making it one of the largest platforms for musical performance. Serena Williams appeared in the audience dancing during the performance, underscoring celebrity draw and cultural significance. Kendrick's halftime show performance was universally praised as one of the greatest Super Bowl halftime spectacles — rivalling performances by Michael Jackson, Prince, and Beyoncé. The halftime show amplified 'Not Like Us' to unprecedented global exposure, weeks after his Grammy sweep (5/5 wins). New Orleans' rich musical heritage (jazz, R&B, hip-hop) made it culturally appropriate venue for Kendrick's showcase. The Super Bowl LIX halftime show represented hip-hop's dominance in American popular culture. Kendrick's February 2025 visibility through Grammys (Feb 2) and Super Bowl (Feb 9) cemented his status as hip-hop's preeminent artist. The performance demonstrated how Super Bowl halftime shows serve as cultural touchstones validating artists' global influence beyond music charts.","folder":"AP_HC","topic":"International_Current_Affairs"},

    # ── Booker Prize 2025 & Pulitzer 2025 (23018-23022) ──
    {"id":23018,"question_text":"The Booker Prize 2025 was won by which novel, announced at a London ceremony on November 10, 2025?","option_a":"James by Percival Everett","option_b":"Flesh by David Szalay","option_c":"Orbital by Samantha Harvey","option_d":"The God of the Woods by Lauren Fox","correct_answer":"B","explanation":"Booker Prize 2025: 'Flesh' by David Szalay — a British-Canadian author of Hungarian descent — won the prestigious £50,000 prize announced November 10, 2025 at a London ceremony. The prize was presented by 2024 Booker Prize winner Samantha Harvey ('Orbital'), perpetuating the award ceremony tradition. Szalay had previously been shortlisted for the Booker Prize for his 2016 novel 'All That Man Is' — a multi-narrative work about European men at different life stages. 'Flesh' explores themes of desire, mortality, class aspiration, and human vulnerability through sparse, elegant prose following an Hungarian man named István from adolescence through old age. Szalay's win made him the first Hungarian-British author to win the Booker Prize, underscoring Central European literature's growing prominence in English-language literary prizes. His win occurred the same year Nobel Literature 2025 went to Hungarian László Krasznahorkai — making 2025 a remarkable year for Hungarian literature's global recognition. The Booker Prize's international reach (open to English-language fiction from Commonwealth, Ireland, and other English-publishing nations) has increasingly championed European voices. Szalay's sparse narrative style and philosophical exploration of human existence represent contemporary literary excellence, challenging conventional storytelling. The 2025 Booker Prize affirmed how international authors reshape English-language literature canon.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23019,"question_text":"International Booker Prize 2025 was won by 'A Cage Went in Search of a Bird' — an anthology inspired by which author's aphorisms?","option_a":"Leo Tolstoy","option_b":"Franz Kafka","option_c":"Albert Camus","option_d":"Marcel Proust","correct_answer":"B","explanation":"International Booker Prize 2025: 'A Cage Went in Search of a Bird' — an innovative anthology anthology comprising ten stories written by ten authors, each inspired by a different aphorism from Franz Kafka. The title directly derives from Kafka's aphorism: 'A cage went in search of a bird.' This meta-literary experiment celebrates Kafka's influence on contemporary world literature — demonstrating how a single author's philosophical insights can generate diverse creative responses across cultures and genres. The International Booker Prize recognises excellence in literary translation — honouring both original author and translator equally (prize money £50,000 shared between). Open to any fiction originally published outside Britain/Ireland and translated into English, the award championed world literature's accessibility to English-reading audiences. Kafka's aphorisms are prized for their paradoxical wisdom about existence, power, freedom, and meaning — universal concerns transcending early-20th-century Prague. The anthology's concept validates Kafka's enduring literary legacy over a century after his death (1924). This recognition of translated fiction reflects global publishing industry's commitment to cross-cultural understanding. The 2025 International Booker Prize exemplifies how contemporary literature builds upon canonical writers, reinterpreting their work for new generations. The prize's celebration of translation affirms literature's role in international dialogue and cultural bridge-building.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23020,"question_text":"Pulitzer Prize 2025 for Fiction went to 'James' by Percival Everett — a retelling of which classic American novel from the perspective of an enslaved man?","option_a":"To Kill a Mockingbird","option_b":"Adventures of Huckleberry Finn","option_c":"Uncle Tom's Cabin","option_d":"Beloved","correct_answer":"B","explanation":"Pulitzer Prize 2025 for Fiction: 'James' by Percival Everett — a transformative retelling of Mark Twain's 'Adventures of Huckleberry Finn' (1884) from Jim's perspective — the enslaved man who becomes fugitive companion to protagonist Huck. Everett's 'James' reimagines Jim as an educated, complex, psychologically developed character with agency and interiority — countering Twain's original portrayal as a sympathetic but ultimately stereotyped enslaved person. This reimagining represents contemporary Black literature's reclamation of canonical American texts, centring voices historically marginalised or objectified. Everett's novel became a bestseller and swept literary prizes (Pulitzer Fiction 2025, PEN/Faulkner Award, Carnegie Medal for Excellence in Fiction, Kirkus Prize). The Pulitzer Prizes are administered by Columbia University, New York, and represent American literature's highest honours. Everett, a Distinguished Professor at University of Southern California, represents Black American literary excellence challenging literary canon. His work joins contemporary fiction (Colson Whitehead's 'The Underground Railroad,' Yaa Gyasi's 'Homegoing') recentring enslaved people's narratives in American literature. 'James' exemplifies how contemporary fiction revises historical narratives, offering suppressed perspectives. The 2025 Pulitzer Fiction Prize validated Everett's artistic contribution to American letters and demonstrated Pulitzer committee's commitment to celebrating innovative, socially conscious fiction.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23021,"question_text":"Who won the Pulitzer Prize 2025 for Poetry with 'What the Earth Seemed to Say: New & Selected Poems'?","option_a":"Louise Glück","option_b":"Ocean Vuong","option_c":"Marie Howe","option_d":"Tracy K. Smith","correct_answer":"C","explanation":"Pulitzer Prize 2025 for Poetry: Marie Howe — for 'What the Earth Seemed to Say: New & Selected Poems,' a comprehensive retrospective collection spanning her career. Howe is celebrated for her accessible yet profound exploration of ordinary life transformed through attention and spirituality. Her best-known poem 'What the Living Do' (1997) is a meditation on grief following her brother's death from AIDS — a landmark poem in contemporary American poetry addressing loss and resilience. 'The Kingdom of Ordinary Time' (2008) extends these themes through spiritual questioning and intimate observation. Howe serves as Poet Laureate of New York State (2019-present), using the platform to champion poetry's accessibility to diverse audiences. Her Pulitzer Prize 2025 recognises a lifetime of contributions to American poetry and her distinctive voice addressing mortality, spirituality, family, and human connection with unflinching honesty. Howe's poetry has influenced generations of American poets and remains widely anthologised. Her award validates contemplative, narrative-driven poetry in an era of experimental forms. The Pulitzer Prizes for Poetry recognise literary excellence in America's most prestigious competition. Pulitzer Music 2025: Susie Ibarra (Filipino-American composer) for 'Sky Islands' — bridging contemporary classical, jazz, and indigenous traditions.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23022,"question_text":"Pulitzer Prize 2025 for Music was won by Filipino-American Susie Ibarra for 'Sky Islands.' She is primarily known as which type of musician?","option_a":"Classical violinist","option_b":"Jazz pianist","option_c":"Composer and percussionist","option_d":"Electronic music producer","correct_answer":"C","explanation":"Pulitzer Prize 2025 for Music: Susie Ibarra (Filipino-American composer and percussionist) won for 'Sky Islands' — a composition inspired by Philippine cloud forests and the rhythmic traditions of indigenous Tagalog music. Ibarra's work distinctly bridges contemporary classical composition, avant-garde jazz, and Filipino indigenous musical traditions — creating hybrid forms celebrating her cultural heritage while innovating Western art music. Her percussion mastery encompasses traditional instruments (timpani, vibraphone, bells) and unconventional sound sources, crafted into sophisticated harmonic structures. The Pulitzer Prize recognises her substantial contributions to American concert music and cross-cultural artistic bridge-building. 'Sky Islands' specifically references the Luzon highlands' ecological uniqueness and cultural richness, demonstrating how contemporary classical music can address environmental and cultural themes. Ibarra represents Filipino diaspora artists achieving international recognition while maintaining cultural authenticity. The Pulitzer Prize validates her decades-long contributions to American new music and international contemporary classical circles. Pulitzer Prizes are awarded annually by Columbia University, New York, in journalism, letters, drama, music, and special categories — America's most prestigious literary and artistic honours. Ibarra's 2025 Music Prize affirms how contemporary composers integrate global traditions, expanding classical music's definition beyond European conventions.","folder":"AP_HC","topic":"International_Current_Affairs"},

    # ── Ballon d'Or 2025 & India Sports Awards (23023-23027) ──
    {"id":23023,"question_text":"Who won the Men's Ballon d'Or 2025 after his club won a historic treble (including their first ever UEFA Champions League)?","option_a":"Vinicius Jr (Real Madrid)","option_b":"Lamine Yamal (Barcelona)","option_c":"Ousmane Dembélé (PSG)","option_d":"Kylian Mbappé (Real Madrid)","correct_answer":"C","explanation":"Men's Ballon d'Or 2025: Ousmane Dembélé (France, Paris Saint-Germain) — defeating runner-up Lamine Yamal (Barcelona). Dembélé won for his transformative 2024-25 season leading PSG to a historic treble: Ligue 1 title, Coupe de France, and PSG's FIRST EVER UEFA Champions League triumph — a watershed moment in Paris's football ambitions. His performance was decisive (35 goals in 53 appearances). At age 28, Dembélé became the 6th Frenchman to win the Ballon d'Or, joining elite company: Raymond Kopa, Michel Platini, Jean-Pierre Papin, Zinédine Zidane, and Karim Benzema. His award signifies French football excellence and PSG's emergence as European elite. The treble victory ended decades of Champions League disappointment and transformed PSG's continental narrative. Women's Ballon d'Or 2025: Aitana Bonmatí (Spain, Barcelona) — her third consecutive win, cementing dominance. The award recognises international football excellence and celebrates players elevating their clubs to historic achievements. Dembélé's recognition validates his 2023 transfer to PSG as transformative for French football profile and European club competition.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23024,"question_text":"Aitana Bonmatí won Women's Ballon d'Or 2025. This was her how many consecutive wins?","option_a":"First","option_b":"Second consecutive","option_c":"Third consecutive","option_d":"Fourth consecutive","correct_answer":"C","explanation":"Aitana Bonmatí (Spain, FC Barcelona) achieved an extraordinary hat-trick with her THIRD consecutive Women's Ballon d'Or win in 2025 (previously 2023 and 2024) — joining an elite historical company of players with multiple consecutive awards. Bonmatí is widely acknowledged as the world's best women's footballer, characterised by exceptional technical brilliance, creative playmaking, positional intelligence, and game intelligence. Her style combines precision passing, dribbling ability, and football intelligence elevating FC Barcelona's attacking play. She was the standout performer in Spain's 2023 FIFA Women's World Cup triumph in Australia, catalysing the tournament and elevating women's football globally. Bonmatí's dominance reflects Barcelona's success as Europe's women's football powerhouse. Her consecutive Ballon d'Or wins validate women's football's elevation within global sports awards and recognition systems. The thrice-consecutive award demonstrates sustained excellence and dominance rarely achieved. Bonmatí represents Spanish football's gender equity progress and women athletes' increasing visibility in mainstream sports recognition. Her three awards exemplify how women's sports excellence is increasingly honoured equally with men's achievements in international award ceremonies.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23025,"question_text":"Major Dhyan Chand Khel Ratna Award 2025 was given to four athletes on January 17, 2025. Which was NOT among the winners?","option_a":"Gukesh D (Chess)","option_b":"Manu Bhaker (Shooting)","option_c":"Neeraj Chopra (Athletics)","option_d":"Harmanpreet Singh (Hockey)","correct_answer":"C","explanation":"Major Dhyan Chand Khel Ratna Award 2025 (awarded January 17, 2025 at Rashtrapati Bhavan by President Droupadi Murmu): The four 2025 recipients were: Gukesh D (Chess — youngest World Chess Champion ever), Harmanpreet Singh (Hockey — India's men's hockey captain), Praveen Kumar (Para-Athletics — Paralympic success), Manu Bhaker (Shooting — first Indian woman to win two Olympic medals in single Olympics, Paris 2024 bronze). Neeraj Chopra, the celebrated javelin thrower, had previously won the Major Dhyan Chand Khel Ratna in 2021 (post his Tokyo 2020 gold medal), not in 2025. The Khel Ratna Award represents India's highest sporting honour, recognising exceptional athletic achievement and global competitiveness. The 2025 cohort exemplified India's multi-sport excellence (chess, hockey, para-sports, shooting) demonstrating diversified athletic achievement beyond traditional cricket dominance. This award affirmed India's emergence as a sporting nation producing world-class athletes across disciplines. Named after legendary hockey player Major Dhyan Chand, the award carries immense prestige in Indian sports culture.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23026,"question_text":"Manu Bhaker (Khel Ratna 2025) won two bronze medals at Paris Olympics 2024 — the first Indian to win two medals in a single Olympics since whom in 1900?","option_a":"Milkha Singh","option_b":"P.T. Usha","option_c":"Norman Pritchard","option_d":"K.D. Jadhav","correct_answer":"C","explanation":"Manu Bhaker won two bronze medals at the Paris 2024 Olympics — a historic achievement: 10m air pistol individual and 10m air pistol mixed team (with partner Sarabjot Singh). She became the first Indian athlete to win two Olympic medals in a single Olympics since Norman Pritchard of 1900 Paris Olympics (who won 2 silver medals in athletics track events). Bhaker's dual medals represent a breakthrough for Indian Olympic shooting — establishing India's shooting prowess on the world stage. She received the Major Dhyan Chand Khel Ratna Award 2025 in recognition. Trained by legendary shooting coach Jaspal Rana, Bhaker is from Jhajjar, Haryana. Her performance elevated Indian women athletes' Olympic visibility. Norman Pritchard, competing for British India, remains historically significant but Bhaker's 2024 achievement represents independent India's sporting capability. Her bronze medals catapulted Indian shooting into discussions of medal contention for future Olympics. The two-medal achievement demonstrated sustained excellence across multiple shooting formats and competitive pressures.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23027,"question_text":"Gukesh Dommaraju (Khel Ratna 2025) became the youngest World Chess Champion in December 2024 at what age, defeating Ding Liren?","option_a":"17","option_b":"18","option_c":"19","option_d":"20","correct_answer":"B","explanation":"D. Gukesh Dommaraju (India) achieved a historic milestone becoming the World Chess Champion in December 2024 at age 18 — the youngest ever, surpassing Garry Kasparov's longstanding record set in 1985 at age 22. Gukesh defeated China's Ding Liren in Game 14 of the World Chess Championship match held in Singapore — a fiercely competitive encounter validating his status. His victory represented India's chess excellence on the global stage, building on Vishwanathan Anand's legacy. Gukesh is from Chennai, Tamil Nadu and trained through Anand's chess development programmes, exemplifying India's chess infrastructure supporting young talent. His Khel Ratna 2025 award recognised his exceptional sporting achievement elevating India's global prestige. At 18, Gukesh became India's youngest Khel Ratna recipient, signifying generational transition in Indian chess. His world title positioned India as a chess superpower, with multiple grandmasters achieving international recognition. Gukesh's achievement inspired millions of Indian youth toward chess excellence. The December 2024 world championship victory represented India's soft power through intellectual sporting achievement, challenging traditional sporting hierarchies dominated by athletics/cricket. His record-breaking youth championship exemplifies how modern chess training, sponsorship, and infrastructure enable precocious excellence.","folder":"AP_HC","topic":"International_Current_Affairs"},

    # ── 83rd Golden Globe Awards — January 11, 2026 (23028-23032) ──
    {"id":23028,"question_text":"Which film won Best Motion Picture — Drama at the 83rd Golden Globe Awards (January 11, 2026)?","option_a":"Sinners","option_b":"One Battle After Another","option_c":"Hamnet","option_d":"I'm Still Here","correct_answer":"C","explanation":"83rd Golden Globe Awards (January 11, 2026, Beverly Hilton Hotel, Beverly Hills): Best Motion Picture — Drama: 'Hamnet' — an adaptation of Maggie O'Farrell's acclaimed 2020 novel reimagining Agnes Hathaway (Shakespeare's wife) and their son Hamnet's death in 1596. Best Motion Picture — Comedy/Musical: 'One Battle After Another' (Paul Thomas Anderson's Gravity's Rainbow adaptation). Paul Thomas Anderson won Best Director AND Best Screenplay for 'One Battle.' Jessie Buckley won Best Actress Drama for 'Hamnet.' Nikki Glaser hosted the ceremony for the second consecutive year (also hosted 82nd Golden Globes 2025), bringing sharp comedic hosting reinforcing the Globes' entertainment value. The 2026 Golden Globes represented the zenith of awards season, beginning the march toward Oscars (March 2026). 'Hamnet' emerged as a frontrunner film early in awards season. The Globes' dramatic category winners typically forecast Oscar contention. The ceremony's January timing positions it strategically within the annual awards calendar. Golden Globes, presented by the Hollywood Foreign Press Association (HFPA), represent international film critics' perspectives, often championing diverse and artistic cinema.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23029,"question_text":"The 83rd Golden Globes 2026 introduced which brand-new category — won by 'Good Hang with Amy Poehler'?","option_a":"Best Streaming Series","option_b":"Best Podcast","option_c":"Best AI-Generated Film","option_d":"Best International Film","correct_answer":"B","explanation":"83rd Golden Globes (January 2026) introduced 'Best Podcast' as a brand-new award category — won by 'Good Hang with Amy Poehler,' hosted by renowned comedian and actress Amy Poehler. The introduction reflects the explosive growth of celebrity-led podcast culture and podcasting's emergence as a significant entertainment medium competing with traditional television and film. Podcasts have become billion-dollar industries with major studios, celebrities, and platforms (Spotify, Apple Podcasts, Amazon Music) investing heavily. The Globes' recognition legitimises podcasting within mainstream entertainment honours. 'Good Hang with Amy Poehler' represents the conversational podcast format gaining cultural currency — intimate, unscripted dialogue attracting millions globally. The category addition signals awards ceremonies adapting to evolving media consumption patterns. Younger audiences (Gen Z, millennials) consume substantial entertainment via podcasts over traditional formats. The Golden Globes, presented by the Hollywood Foreign Press Association (HFPA) at the Beverly Hilton Hotel Beverly Hills, California, continue expanding categories reflecting contemporary entertainment landscape. The podcast category demonstrates how awards institutions evolve recognising emerging creative forms and media technologies reshaping entertainment.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23030,"question_text":"Paul Thomas Anderson won Best Director at the 83rd Golden Globes 2026 for 'One Battle After Another.' This film is an adaptation of which Thomas Pynchon novel?","option_a":"The Crying of Lot 49","option_b":"Vineland","option_c":"Gravity's Rainbow","option_d":"Mason & Dixon","correct_answer":"C","explanation":"'One Battle After Another' (Paul Thomas Anderson, 2026) is an audacious adaptation of Thomas Pynchon's 'Gravity's Rainbow' (1973) — widely considered one of the most celebrated, challenging, and difficult American novels ever written. 'Gravity's Rainbow' is a sprawling 760-page postmodern epic set during WWII exploring themes of paranoia, power, technology, and human agency amid geopolitical chaos. PTA had previously adapted another Pynchon work, 'Inherent Vice' (2014), demonstrating affinity for Pynchon's eccentric narrative styles. 'Gravity's Rainbow' won the National Book Award in 1974 despite widespread critical debate about its comprehensibility and merit — it represents American literary ambition at its most extreme. The novel's adaptation into cinema seemed nearly impossible given its fragmented narrative, experimental structure, and philosophical density. PTA's directorial accomplishment in translating this notoriously difficult novel into visual cinema earned him Best Director at the 83rd Golden Globes. The film went on to win Best Picture at the 98th Oscars (March 2026), validating the adaptation's artistic success. PTA's 'One Battle' exemplified how visionary directors elevate literary source material into cinematic achievements, translating prose complexity into visual storytelling.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23031,"question_text":"Best Original Song at the 83rd Golden Globes 2026 was 'Golden' from which animated film that later also won the Oscar?","option_a":"Zootopia 2","option_b":"KPop Demon Hunters","option_c":"Avatar: Fire and Ash","option_d":"Moana 3","correct_answer":"B","explanation":"Best Original Song at 83rd Golden Globes (January 2026): 'Golden' from 'KPop Demon Hunters' (Sony Pictures Animation) — an innovative animated film blending contemporary K-pop music culture with action-adventure storytelling. The song 'Golden' was composed specifically for the film, showcasing contemporary pop music's integration into animated cinema. The film's musical identity became central to its cultural appeal and critical success. 'KPop Demon Hunters' demonstrated Hollywood animation's evolution incorporating global music trends and cultural aesthetics. The same film ('KPop Demon Hunters') subsequently won Best Animated Feature AND Best Original Song again at the 98th Academy Awards (March 2026) — an unprecedented sweep validating its excellence across both animation and musical categories. This dual-award victory established 'KPop Demon Hunters' as the dominant animated film of the 2025-2026 awards season, sweeping major ceremonies. Sony Pictures Animation, known for the Spider-Verse films, leveraged its animation expertise and music partnerships to create a culturally resonant film. The awards trajectory demonstrated how contemporary animated films achieve parity with live-action in prestige ceremonies. 'Golden' became a streaming phenomenon, validating the integration of K-pop aesthetics into mainstream American entertainment.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23032,"question_text":"At the 83rd Golden Globes 2026, who hosted the ceremony for the second consecutive year?","option_a":"Jo Koy","option_b":"Jerrod Carmichael","option_c":"Quinta Brunson","option_d":"Nikki Glaser","correct_answer":"D","explanation":"Nikki Glaser hosted the 83rd Golden Globes (January 2026) for the second consecutive year — a rare honour reflecting her exceptional hosting success. She had previously hosted the 82nd Golden Globes (January 2025) to widespread critical acclaim and audience appreciation. Her 2025 hosting was widely praised as one of the sharpest, funniest, and most engaging Golden Globes ceremonies in recent years, reinvigorating the awards show's entertainment value. Glaser's comedic timing, irreverent humour, and ability to navigate celebrity culture made her a standout host. Her successful repeat engagement demonstrates the Globes' confidence in her ability to deliver engaging television. Glaser replaced the long-tenure hosting era of Ricky Gervais, who hosted the Globes five times (2010-2020) and became synonymous with the ceremony. By contrast, Jo Koy's 2024 Golden Globes hosting was widely criticised as unfunny and awkward, validating the selection committee's pivot to Glaser. The 2026 repeat hosting indicated Glaser's popularity with industry and audiences. Her successful second hosting year positioned her as a permanent fixture for future Golden Globes ceremonies, potentially transforming host succession in awards television. Glaser exemplified how comedians can reinvigorate awards show formats through sharp, intelligent humour.","folder":"AP_HC","topic":"International_Current_Affairs"},

    # ── 68th Grammy Awards — February 1, 2026 (23033-23040) ──
    {"id":23033,"question_text":"Which album won Album of the Year at the 68th Grammy Awards (February 1, 2026) — the first Spanish-language album to win the category?","option_a":"El Último Tour del Mundo — Bad Bunny","option_b":"Debí Tirar Más Fotos — Bad Bunny","option_c":"Un Verano Sin Ti — Bad Bunny","option_d":"Nadie Sabe Lo Que Va a Pasar — Bad Bunny","correct_answer":"B","explanation":"68th Grammy Awards (February 1, 2026): Album of the Year: Bad Bunny's 'Debí Tirar Más Fotos' — a historic achievement as the first-ever Spanish-language album to win the Grammy's highest honour. Bad Bunny became the third Latino artist to win Album of the Year, following precedent-setting wins. Released January 5, 2026 (strategically weeks before Grammys), 'Debí Tirar Más Fotos' blends Puerto Rican musical traditions: salsa, reggaeton, and plena — celebrating Puerto Rican cultural identity and nostalgia. The title translates 'I Should Have Taken More Photos' — evoking memory and cherishing moments. The album represents Puerto Rican cultural affirmation on the global stage, validating non-English language music at Grammy's top level. Bad Bunny's win signified the Grammys' evolution recognising Latin music's commercial dominance and cultural significance. The recognition addressed historical underrepresentation of Spanish-language music at major awards ceremonies. Bad Bunny, a Puerto Rican global superstar, leverages reggaeton and Latin trap to achieve unprecedented streaming numbers. His 2026 AOTY win represented Latin music's global ascendancy and Grammys' belated inclusivity. The award validated Puerto Rico's musical excellence and diaspora artists' international influence.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23034,"question_text":"Kendrick Lamar won Record of the Year at the 68th Grammys 2026 for 'Luther' (feat. SZA). This made him the first rapper to win this award consecutively — how many consecutive wins?","option_a":"First time winning","option_b":"Second consecutive","option_c":"Third consecutive","option_d":"Fourth","correct_answer":"B","explanation":"68th Grammy Awards (February 2026): Kendrick Lamar won Record of the Year for 'Luther' (feat. SZA) — his SECOND consecutive Record of the Year win, establishing an unprecedented streak. He previously won Record of the Year at the 67th Grammys (February 2025) for 'Not Like Us,' making him the first rapper to achieve consecutive Record of the Year honours. The 'Luther' collaboration with SZA represented seamless musical partnership between two hip-hop titans. With five wins at the 68th Grammys ceremony alone, Lamar surpassed Jay-Z's Grammy total of 21 awards, becoming the most-awarded hip-hop artist in Grammy history with 27+ total Grammys. This achievement validated Kendrick's artistic supremacy within hip-hop and broader music industry. His consecutive Record of the Year wins demonstrated sustained excellence and relevance across calendar years. 'Luther' became a streaming mega-hit, validating both artist's combined commercial and critical power. Kendrick's Grammy dominance positioned him as hip-hop's preeminent contemporary voice, transcending generational divides. His 68th Grammy wins cemented his legacy as one of music's greatest artists.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23035,"question_text":"'Wildflower' won Song of the Year at the 68th Grammys 2026. Who co-wrote and performed this Grammy winner?","option_a":"Taylor Swift and Jack Antonoff","option_b":"Billie Eilish and Finneas O'Connell","option_c":"Olivia Rodrigo and Dan Nigro","option_d":"SZA and Kendrick Lamar","correct_answer":"B","explanation":"68th Grammy Awards (February 2026): Song of the Year: 'Wildflower' by Billie Eilish and brother Finneas O'Connell. This achieved an extraordinary milestone as their THIRD Song of the Year Grammy win — validating unparalleled creative partnership spanning multiple album cycles. Their previous Song of the Year wins: 'No Time to Die' (64th Grammy Awards 2022, from the James Bond film) and 'What Was I Made For?' (66th Grammy Awards 2024, from the Barbie movie). Both Billie and Finneas individually became the most-awarded artists in the Song of the Year category in Grammy history, surpassing previous record-holders. Their sibling collaboration represents modern music production where artist-producer partnerships become creatively synonymous. 'Wildflower' showcases their sonic signature: minimalist production, introspective vocals, and sophisticated arrangement. Their three-time Song of the Year achievement reflects consistent excellence, evolving artistry, and Grammy voters' recognition of contemporary pop excellence. Billie Eilish, as the youngest EGOT-eligible artist (requiring Emmy, Grammy, Oscar, Tony), continues building toward this historic achievement. The repeated honours signify how Grammy voters prioritise songwriting excellence and production innovation in contemporary music.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23036,"question_text":"Who won Best New Artist at the 68th Grammy Awards 2026, becoming the 9th consecutive woman to win and first British winner since Dua Lipa?","option_a":"Sabrina Carpenter","option_b":"Gracie Abrams","option_c":"Doechii","option_d":"Olivia Dean","correct_answer":"D","explanation":"68th Grammy Awards (February 2026): Best New Artist: Olivia Dean — a British singer-songwriter who achieved a historic milestone as the 9th consecutive woman to win Best New Artist, demonstrating the category's female-dominated trajectory. She became the first British winner since Dua Lipa's 2019 Best New Artist win, representing the UK's continued musical export excellence. Olivia Dean is known for soul-influenced pop blending R&B sensibilities with contemporary production. Her album 'Messy' showcases vocal sophistication and emotional nuance earning critical acclaim. Based in London, her musical style draws comparisons to Amy Winehouse — the iconic British jazz-soul artist whose tragic early death (2011) left a legacy for subsequent British female artists. Dean's award acknowledges her vocal excellence, songwriting maturity, and potential to shape contemporary pop music. The 9th consecutive woman to win demonstrates Grammy voters' recognition of emerging female talent dominance in contemporary music landscape. Her win continued a pattern showing women increasingly define pop music's cutting edge. Olivia Dean's 2026 win positioned her for sustained international career and influence shaping pop music's direction in the late 2020s.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23037,"question_text":"Bad Bunny (Album of Year at 68th Grammys 2026) is from which Puerto Rican city?","option_a":"San Juan","option_b":"Ponce","option_c":"Vega Baja","option_d":"Bayamón","correct_answer":"C","explanation":"Bad Bunny (Benito Antonio Martínez Ocasio) is from Vega Baja, Puerto Rico — born May 10, 1994. He studied audio-visual communication at the University of Puerto Rico before pursuing music full-time. His breakthrough came through SoundCloud and reggaeton collaborations with established artists. His 68th Grammy Awards Album of the Year 2026 win for 'Debí Tirar Más Fotos' represented triumphant validation of Puerto Rican musical traditions — celebrating salsa, reggaeton, and plena rhythms as globally significant artistic expressions. The album's nostalgic title ('I Should Have Taken More Photos') reflected personal reflection and cultural pride. Bad Bunny is one of the most-streamed artists globally on Spotify, consistently breaking streaming records. His collaborations span reggaeton, trap latino, and crossover pop, positioning him as reggaeton's global ambassador. His 2026 Grammy victory elevated Puerto Rican artists' visibility internationally and validated Spanish-language music at the highest industry honours. Bad Bunny's success exemplifies how diaspora artists can maintain cultural authenticity while achieving unprecedented global commercial success. His Grammy win affirmed Puerto Rico's cultural richness beyond stereotypes.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23038,"question_text":"At the 68th Grammys 2026, Kendrick Lamar surpassed Jay-Z as the most-awarded hip-hop artist. Approximately how many total Grammys does Lamar hold?","option_a":"15","option_b":"22","option_c":"27","option_d":"35","correct_answer":"C","explanation":"Kendrick Lamar's five-win haul at the 68th Grammy Awards (February 2026) brought his total Grammy count to approximately 27, surpassing Jay-Z's previous record of 21 Grammys. This achievement made Lamar the most-awarded hip-hop artist in Grammy history. His 2026 wins included Record of the Year ('Luther' feat. SZA) plus four additional awards across categories. His career Grammy accumulation included 5 wins at the 67th Grammys (2025) for 'Not Like Us' sweep; 5 wins at the 59th Grammys (2017) for 'DAMN.' album; and numerous earlier wins spanning his career. Kendrick Lamar is from Compton, California — a city synonymous with West Coast hip-hop excellence. His trajectory from Compton to Grammy dominance represents contemporary hip-hop's artistic legitimacy and commercial power. Surpassing Jay-Z (hip-hop's previous titan) symbolised generational succession and changing hip-hop landscape priorities toward lyrical substance and artistic innovation. His 27 Grammy count positioned him among the most-awarded musicians across all genres, validating hip-hop's mainstream prominence. Kendrick's Grammy achievement represents African American cultural excellence achieving unprecedented industry recognition.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23039,"question_text":"'Debí Tirar Más Fotos' (Grammy Album of Year 2026) was released by Bad Bunny on January 5, 2026. Which Puerto Rican music genre is central to this album?","option_a":"Merengue and cumbia","option_b":"Salsa, reggaeton, and plena","option_c":"Bachata and dembow","option_d":"Soca and calypso","correct_answer":"B","explanation":"Bad Bunny's 'Debí Tirar Más Fotos' (Grammy Album of the Year 2026) is fundamentally rooted in Puerto Rican musical traditions: salsa, reggaeton, and plena. These three genres represent different historical layers of Puerto Rican culture — salsa rooted in Cuban-Puerto Rican jazz-dance fusion (1960s-70s); reggaeton emerging from Jamaican dancehall adapted to Puerto Rican production (1980s-90s); and plena — a percussion-driven Puerto Rican folk genre dating to colonial era featuring storytelling through rhythmic patterns. The album's title 'Debí Tirar Más Fotos' translates 'I Should Have Taken More Photos' — embodying nostalgic reflection on Puerto Rican cultural memories and identity. Released strategically January 5, 2026 — just one month before the 68th Grammy Awards — the album captured Puerto Rican cultural moment and became immediate commercial success. The strategic release timing ensured Grammy voter familiarity and streaming momentum. Bad Bunny's grammy victory for celebrating Puerto Rican authenticity signified international validation of Caribbean musical traditions. The album demonstrates contemporary artists' commitment to cultural specificity while achieving global commercial success. The Grammy win affirmed Puerto Rico's musical significance on world stage.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23040,"question_text":"The 68th Grammy Awards 2026 were held on which date and at which venue?","option_a":"January 15, 2026 — Madison Square Garden, New York","option_b":"February 1, 2026 — Crypto.com Arena, Los Angeles","option_c":"February 8, 2026 — Staples Center, Los Angeles","option_d":"March 2, 2026 — Radio City Music Hall, New York","correct_answer":"B","explanation":"68th Grammy Awards: February 1, 2026 at Crypto.com Arena, Los Angeles. Consecutive Grammy ceremonies have been held at Crypto.com Arena (formerly Staples Center), establishing Los Angeles as the Grammy's permanent venue — centralising the award show within the music industry's Hollywood nexus. The February 1, 2026 date positioned the Grammys strategically within the annual awards season calendar — following Golden Globes (January) and preceding the Academy Awards (March). This timing amplifies media coverage and industry attention. Bad Bunny won Album of the Year for 'Debí Tirar Más Fotos' — historic first Spanish-language AOTY. Kendrick Lamar won Record of the Year for 'Luther' — his second consecutive Record of Year win, cementing hip-hop dominance. Billie Eilish won Song of the Year for 'Wildflower' — her third Song of Year triumph. Olivia Dean won Best New Artist as the ninth consecutive female winner in the category. The 2026 ceremony epitomised contemporary Grammy's recognition of genre diversity (Latin, hip-hop, pop), female artist prominence, and international music industry representation at America's premier music awards show.","folder":"AP_HC","topic":"International_Current_Affairs"},

    # ── 79th BAFTA Film Awards — February 22, 2026 (23041-23047) ──
    {"id":23041,"question_text":"Which film won Best Film at the 79th BAFTA Film Awards (February 22, 2026) with a leading 6 wins?","option_a":"Sinners","option_b":"Hamnet","option_c":"One Battle After Another","option_d":"Sentimental Value","correct_answer":"C","explanation":"79th British Academy Film and Television Arts (BAFTA) Awards (February 22, 2026, Royal Festival Hall, London): Best Film: 'One Battle After Another' (Paul Thomas Anderson adaptation of Thomas Pynchon's 'Gravity's Rainbow') — dominated the evening with a leading six awards. The film's sweep included: Best Film, Best Director (Paul Thomas Anderson), Best Adapted Screenplay (PTA), Best Supporting Actor (Sean Penn), Best Supporting Actress (Amy Madigan). BAFTA's recognition of 'One Battle' positioned it as the frontrunner heading into the March 2026 Academy Awards. The film's BAFTA sweep validated PTA's directorial audacity translating literary postmodernism into cinema. Hosted by acclaimed Scottish actor Alan Cumming, the ceremony was broadcast on BBC One and BBC iPlayer, reaching millions across the United Kingdom. BAFTA, the British Academy's film honours, represents international film critics' perspective and carries significant Oscars predictive power. 'One Battle's six BAFTA wins signified exceptional filmmaking, cinematography, sound design, editing, and craft execution across multiple technical categories.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23042,"question_text":"Robert Aramayo won Leading Actor at BAFTA 2026. He beat Timothée Chalamet for the award. Aramayo is best known for playing which character in 'The Rings of Power'?","option_a":"Aragorn","option_b":"Elrond","option_c":"Gandalf","option_d":"Legolas","correct_answer":"B","explanation":"Robert Aramayo (British-Spanish actor) won BAFTA Leading Actor 2026, defeating Timothée Chalamet (nominated for 'Sinners'). Aramayo is best known for portraying Elrond (young version, 2000+ years prior to 'Fellowship') in Amazon's epic 'The Rings of Power' (2022-present) — Peter Jackson's successor to his Middle-earth film trilogy. Elrond is the immortal elf-lord and co-founder of Rivendell, a pivotal character in Tolkien lore. Aramayo previously played young Ned Stark in HBO's 'Game of Thrones,' establishing his reputation for playing younger versions of iconic fantasy characters. His 2026 BAFTA Leading Actor award recognised his performance in 'I Swear,' demonstrating range beyond fantasy television. BAFTA Awards (Leading Actress Jessie Buckley for 'Hamnet'; Supporting Actor Sean Penn for 'One Battle After Another'; Supporting Actress Wunmi Mosaku for 'Sinners') affirmed the continuing excellence of ensemble casts in prestige cinema. Aramayo's BAFTA victory positioned him as British cinema's rising male lead.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23043,"question_text":"Wunmi Mosaku won BAFTA Supporting Actress 2026 for which Ryan Coogler film that received a record 16 Oscar nominations?","option_a":"Hamnet","option_b":"Sinners","option_c":"One Battle After Another","option_d":"Weapons","correct_answer":"B","explanation":"79th BAFTA Film Awards (February 2026): Best Supporting Actress: Wunmi Mosaku for 'Sinners' (Ryan Coogler director). 'Sinners' received a record-breaking 16 Academy Award nominations at the 98th Oscars (March 2026) — surpassing previous record of 14 held by 'Titanic' (1997) and 'All About Eve' (1950). Wunmi Mosaku is a Nigerian-British actress celebrated for her performance in 'His House' (2020) — a horror-drama exploring themes of migration and trauma. Her BAFTA recognition affirmed her significant supporting role in 'Sinners.' Michael B. Jordan won Best Actor at the 98th Oscars for 'Sinners,' playing twin brothers. The film ultimately won 4 Oscars from its record 16 nominations (Best Actor, Original Screenplay, Cinematography, Film Editing). Ryan Coogler, the acclaimed director, achieved mainstream recognition for 'Black Panther' (2018) and 'Black Panther: Wakanda Forever' (2022) before 'Sinners.' The film's record 16 nominations signified major studio (Paramount) commitment to ambitious African American filmmaking. 'Sinners' represented contemporary Black cinema achieving unprecedented scale and industry recognition.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23044,"question_text":"'Hamnet' won Outstanding British Film at BAFTA 2026. The film is based on whose 2020 novel?","option_a":"Hilary Mantel","option_b":"Ian McEwan","option_c":"Maggie O'Farrell","option_d":"Zadie Smith","correct_answer":"C","explanation":"'Hamnet' (2026) is based on Maggie O'Farrell's acclaimed 2020 novel, a literary achievement that reimagines the life of Agnes Hathaway (Shakespeare's wife) and explores the devastating death of their 11-year-old son Hamnet in 1596 during an unspecified plague epidemic in Stratford-upon-Avon. The novel fills historical gaps by imagining Agnes's perspective — traditionally marginalised in Shakespeare scholarship. O'Farrell's novel won numerous literary awards and became an international bestseller, establishing her reputation as a major contemporary British author. Jessie Buckley plays Agnes in the film adaptation, delivering a performance that dominated awards season 2025-2026. The film won Outstanding British Film at BAFTA 79th (February 2026), Best Actress Drama at Golden Globes 83rd (January 2026), and Best Actress at Oscars 98th (March 2026) — all for Buckley's exceptional performance. Buckley achieved a 'Grand Slam' by winning all major film awards (SAG, Golden Globes, BAFTA, Oscars) in the same category — an extremely rare accomplishment. The 'Hamnet' film's critical success validated literary adaptation as a prestige cinema vehicle, translating O'Farrell's novelistic imagination into cinematic form.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23045,"question_text":"'Sentimental Value' won Film Not in the English Language at BAFTA 2026. This Norwegian film was directed by whom?","option_a":"Ruben Östlund","option_b":"Joachim Trier","option_c":"Thomas Vinterberg","option_d":"Roy Andersson","correct_answer":"B","explanation":"'Sentimental Value' (Norwegian film) — directed by Joachim Trier — won BAFTA 79th (February 2026) category Film Not in the English Language. Trier is an acclaimed Norwegian-Danish filmmaker known for psychological depth and character-driven narratives. His previous film 'The Worst Person in the World' (2021) won Best Actress at the Cannes Film Festival for Renate Reinsve — a significant international recognition. Trier is known for his Oslo trilogy — a series exploring contemporary Norwegian life, relationships, and existential challenges. 'Sentimental Value' continues Trier's exploration of intimate human experiences and emotional complexity. The film also features Renate Reinsve, establishing a creative partnership between director and actress. Trier represents contemporary Nordic cinema's international prestige — Norwegian and Danish filmmakers achieving recognition at major international film festivals (Cannes, Berlin) and awards ceremonies. 'Sentimental Value's BAFTA win validated Nordic cinema's artistic excellence and thematic depth addressing universal human experiences. The film demonstrates how non-English language cinema can achieve international reach and critical recognition when addressing emotionally resonant narratives. BAFTA's dedicated international film category validates global cinema beyond English-language Hollywood productions.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23046,"question_text":"The 79th BAFTA Film Awards 2026 were held at which iconic London venue?","option_a":"Royal Albert Hall","option_b":"The O2 Arena","option_c":"Royal Festival Hall","option_d":"Barbican Centre","correct_answer":"C","explanation":"79th BAFTA Film Awards (February 22, 2026) were held at the Royal Festival Hall — an iconic concert and arts venue on London's South Bank in the cultural quarter. Hosted by acclaimed Scottish actor Alan Cumming, the ceremony was broadcast on BBC One and BBC iPlayer, reaching millions across the United Kingdom. BAFTA (British Academy of Film and Television Arts, founded 1947) represents British film industry's most prestigious honours. The Royal Festival Hall venue symbolises BAFTA's commitment to London's arts infrastructure and cultural significance. The ceremony's highlights: 'One Battle After Another' won 6 awards (Best Film, Director, Adapted Screenplay, Supporting Actor, Supporting Actress); 'Sinners' won 3 BAFTAs affirming its record 16 Oscar nominations; 'Hamnet' won Outstanding British Film with Jessie Buckley winning Best Actress Drama. Sean Penn won Supporting Actor for 'One Battle.' BAFTA's February ceremony timing positioned it strategically within the annual awards season calendar, forecasting Oscar (March) and validating frontrunner films. The 79th BAFTAs represented British film industry's recognition of cinematic excellence across multiple genres and international films.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23047,"question_text":"Sean Penn won BAFTA Supporting Actor 2026 and Oscar Supporting Actor 2026. How many total Oscars does Penn now hold?","option_a":"One","option_b":"Two","option_c":"Three","option_d":"Four","correct_answer":"C","explanation":"Sean Penn's Best Supporting Actor Oscar at the 98th Academy Awards (2026) for 'One Battle After Another' represents his THIRD Academy Award — a remarkable achievement spanning over two decades. His Oscar history: Best Actor for 'Mystic River' (2003), Best Actor for 'Milk' (2008), and Best Supporting Actor for 'One Battle' (2026). Penn also won BAFTA Supporting Actor 2026 for the same role, creating a dual-award sweep of the prestigious ceremony. Penn's three Oscars position him among the most-decorated actors of his generation. His supporting role in 'One Battle After Another' — Paul Thomas Anderson's adaptation of Thomas Pynchon's 'Gravity's Rainbow' — demonstrated his continued artistic excellence and willingness to engage with challenging material. Penn's career trajectory reflects evolution from celebrated dramatic actor to respected elder statesman of American cinema. His 2026 Oscar victory validated his sustained relevance and artistic depth. Three Oscars across different categories (two Best Actor, one Best Supporting) demonstrate versatility and recognition across multiple decades of filmmaking. Penn's longevity and continued critical recognition exemplify Hollywood's highest-calibre acting standards.","folder":"AP_HC","topic":"International_Current_Affairs"},

    # ── 98th Academy Awards — March 2026 (23048-23062) ──
    {"id":23048,"question_text":"Which film won Best Picture at the 98th Academy Awards (March 2026) with 6 Oscars total including the inaugural Casting award?","option_a":"Sinners","option_b":"Hamnet","option_c":"One Battle After Another","option_d":"Sentimental Value","correct_answer":"C","explanation":"98th Academy Awards (March 2026): Best Picture: 'One Battle After Another' (Paul Thomas Anderson's Gravity's Rainbow adaptation) — won 6 Oscars: Best Picture, Best Director, Best Adapted Screenplay, Best Supporting Actor (Sean Penn), Best Supporting Actress (Amy Madigan), and the inaugural Best Achievement in Casting award. 'One Battle's sweep affirmed critical consensus that the film represented superior filmmaking across multiple craft dimensions. 'Sinners' (Ryan Coogler) received record 16 nominations but won 4 Oscars (Best Actor for Michael B. Jordan, Best Original Screenplay, Best Cinematography, Best Film Editing). 'Frankenstein' won 3 craft Oscars. 'KPop Demon Hunters' achieved the animated sweep with 2 Oscars (Best Animated Feature, Best Original Song). The 98th Oscars represented mainstream cinema recognising ambitious literary adaptation, diverse cast-driven narratives, animated film excellence, and innovative casting direction. 'One Battle's Best Picture victory validated Paul Thomas Anderson's artistic vision translating postmodern literature into cinema. The inaugural Casting award recognised the underappreciated work of casting directors in assembling exceptional ensembles.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23049,"question_text":"Michael B. Jordan won Best Actor at the 98th Oscars 2026 for which film, in which he played twin brothers?","option_a":"One Battle After Another","option_b":"Sinners","option_c":"Creed IV","option_d":"Just Mercy 2","correct_answer":"B","explanation":"98th Academy Awards (March 2026): Best Actor: Michael B. Jordan for 'Sinners' (Ryan Coogler) — his first Oscar win for a career-defining role playing twin brothers with contrasting moral trajectories. 'Sinners' received a record-breaking 16 Oscar nominations and won 4 awards: Best Actor (Jordan), Best Original Screenplay (Ryan Coogler), Best Cinematography, and Best Film Editing. Jordan's performance demonstrated maturity and range, playing complex characters navigating moral choices. He is widely known for 'Black Panther' (2018) as Erik Killmonger — a celebrated MCU antagonist — and the 'Creed' franchise continuing Rocky Balboa's legacy. His 2026 Oscar represented recognition of his transformation from MCU star to serious dramatic actor. Jordan's win validated Ryan Coogler's vision in casting him in a non-superhero prestige role. His Oscar exemplified how contemporary Black actors are increasingly recognized for dramatic excellence at highest industry honours.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23050,"question_text":"Jessie Buckley won Best Actress at the 98th Oscars 2026 for 'Hamnet.' She completed a sweep at all major awards — this is called what?","option_a":"Triple Crown","option_b":"Grand Slam","option_c":"Awards Sweep","option_d":"Clean Slate","correct_answer":"B","explanation":"Jessie Buckley's Best Actress Oscar win at the 98th Academy Awards (March 2026) for 'Hamnet' completed an extraordinary Grand Slam — winning the award category at all four major film awards ceremonies in a single season: Screen Actors Guild Awards + Golden Globes 83rd (January 2026) + BAFTA Film Awards 79th (February 2026) + Academy Awards 98th (March 2026). A Grand Slam achievement in acting is exceptionally rare — fewer than 10 actors have achieved this in cinema history. Buckley is a British-Irish actress from Killarney, County Kerry, Ireland. Her Grand Slam performance in 'Hamnet' (playing Agnes Hathaway, Shakespeare's wife) demonstrated exceptional acting that transcended categories and critical perspectives. The sweep validated her portrayal as universally acclaimed excellence. Buckley's Grand Slam positioned her among cinema's greatest actresses and elevated her profile internationally. Her achievement exemplified how specific roles can achieve cultural resonance across the entire awards industry, creating consensus excellence recognition.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23051,"question_text":"Amy Madigan won Best Supporting Actress at the 98th Oscars 2026 for which film?","option_a":"Sinners","option_b":"Hamnet","option_c":"One Battle After Another","option_d":"Weapons","correct_answer":"D","explanation":"98th Academy Awards (March 2026): Best Supporting Actress: Amy Madigan for 'Weapons' (directed by Gabriel Abrantes). Madigan is a veteran American actress with decades of acclaimed performances, including 'Field of Dreams' (1989) and 'Roe v. Wade' (2021). Her Oscar win represents recognition of continued excellence and artistic depth across her career. Her co-winner on the same evening: Sean Penn (Best Supporting Actor for 'One Battle After Another'). Together, 'Weapons' and 'One Battle After Another' swept both supporting acting categories, demonstrating exceptional ensemble cast quality across prestige cinema. Madigan's Oscar validates the significance of supporting roles in elevating overall film quality and narrative complexity. Her achievement exemplified how veteran actors continue delivering career-defining performances later in their careers.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23052,"question_text":"Ryan Coogler won Best Original Screenplay at the 98th Oscars 2026 for 'Sinners.' His previous directorial debut starred Michael B. Jordan in which film?","option_a":"Black Panther","option_b":"Creed","option_c":"Fruitvale Station","option_d":"Just Mercy","correct_answer":"C","explanation":"Ryan Coogler's directorial debut was 'Fruitvale Station' (2013) — a powerful drama starring Michael B. Jordan as Oscar Grant, a young unarmed Black man whose tragic killing by police in Oakland, California sparked investigations into police brutality. The film launched Coogler's career and established Jordan partnership. Coogler subsequently directed 'Creed' (2015, Rocky franchise continuation), 'Black Panther' (2018, MCU blockbuster), 'Black Panther: Wakanda Forever' (2022), and 'Sinners' (2026). His Oscars Best Original Screenplay win for 'Sinners' recognised Coogler's evolution from documentary-influenced realism to epic prestige narratives. His career trajectory exemplifies Black directors achieving mainstream commercial success while maintaining artistic integrity. Coogler's Oscar validated his screenwriting excellence and vision for complex African American storytelling. His 'Sinners' 16 nominations represented major studio (Paramount) commitment to ambitious Black cinema.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23053,"question_text":"The 98th Oscars 2026 introduced Best Achievement in Casting as a new category. Who won it?","option_a":"Sinners","option_b":"Hamnet","option_c":"One Battle After Another","option_d":"Frankenstein","correct_answer":"C","explanation":"Best Achievement in Casting — a new award category at the 98th Academy Awards (2026) — was won by 'One Battle After Another' in its inaugural year, bringing the film's total Oscar haul to 6 awards. The Academy had deliberated on establishing a Casting category for multiple years, ultimately recognising casting directors' underappreciated work assembling exceptional ensemble casts. The casting director of 'One Battle After Another' thus made Oscar history as the inaugural winner of this previously non-existent category. Casting directors shape film excellence by assembling actors whose chemistry, range, and artistic synergy create compelling narratives. Their work occurs invisible to audiences but profoundly impacts cinematic success. The new category honours this crucial craft. 'One Battle's Best Casting win affirmed the film's exceptional ensemble (Sean Penn, Amy Madigan, and supporting cast) cohesion. The category expansion demonstrated Academy's evolution recognising previously marginalised craft contributions in filmmaking.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23054,"question_text":"'KPop Demon Hunters' won Best Animated Feature at the 98th Oscars 2026. Which studio produced it, known for 'Spider-Verse'?","option_a":"Pixar/Disney","option_b":"DreamWorks","option_c":"Sony Pictures Animation","option_d":"Illumination","correct_answer":"C","explanation":"'KPop Demon Hunters' (Sony Pictures Animation) won Best Animated Feature + Best Original Song ('Golden') at the 98th Academy Awards (2026) — a remarkable sweep of animated categories. Sony Pictures Animation is renowned for the Spider-Verse franchise: 'Spider-Man: Into the Spider-Verse' (2018) and 'Spider-Man: Across the Spider-Verse' (2023) — both Oscar-winning animated films demonstrating the studio's technical innovation and artistic excellence. 'KPop Demon Hunters' exemplified Sony's continued animated film dominance, blending K-pop music culture with action-adventure storytelling. The film's dual-award victories (animated feature and original song) represented unprecedented animated film success at the 2026 Oscars. The same song 'Golden' also won Best Original Song at the 83rd Golden Globes (January 2026), establishing it as a major awards-season presence. Sony Pictures Animation's 2026 success positioned it as Hollywood's preeminent animation studio, rivalling traditional competitors through innovative storytelling and musical integration.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23055,"question_text":"'Sinners' (16 Oscar nominations, 98th Oscars 2026) broke the record for most nominations. Which two films previously shared the record with 14 nominations?","option_a":"Titanic (1997) and All About Eve (1950)","option_b":"La La Land (2016) and The Favourite (2018)","option_c":"Schindler's List (1993) and Shakespeare in Love (1998)","option_d":"Avatar (2009) and The Lord of the Rings (2003)","correct_answer":"A","explanation":"'Sinners' (Ryan Coogler, 2026) achieved the historic distinction of receiving 16 Oscar nominations — breaking the previous record of 14 nominations that had been shared by two films: 'Titanic' (James Cameron, 1997; won 11 Oscars including Best Picture) and 'All About Eve' (Joseph L. Mankiewicz, 1950; won 6). 'La La Land' (2016) also accumulated 14 nominations (won 6 Oscars). 'Sinners' represented unprecedented Oscar recognition within the contemporary era. The film's record 16 nominations reflected major studio (Paramount) investment in ambitious African American cinema on unprecedented scale. Despite record nominations, 'Sinners' won 4 Oscars (Best Actor, Best Original Screenplay, Best Cinematography, Best Film Editing), demonstrating competition across multiple categories. The record nominations validated the film's artistic excellence while reflecting how nominations don't guarantee wins. 'Sinners' record represented international film industry's recognition of contemporary Black cinema significance.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23056,"question_text":"'One Battle After Another' (Best Picture, 98th Oscars 2026) is Paul Thomas Anderson's adaptation of which novelist's work?","option_a":"Don DeLillo","option_b":"Cormac McCarthy","option_c":"Thomas Pynchon","option_d":"David Foster Wallace","correct_answer":"C","explanation":"'One Battle After Another' represents Paul Thomas Anderson's audacious adaptation of Thomas Pynchon's 'Gravity's Rainbow' (1973) — widely considered among the most celebrated yet formidably challenging American novels ever written. 'Gravity's Rainbow' is a 760-page postmodern epic set during WWII exploring paranoia, conspiracy, power, sexuality, and human agency amid geopolitical chaos. Pynchon is famously reclusive — no authenticated photographs exist since the 1950s, maintaining complete public anonymity despite literary fame. PTA had previously adapted Pynchon's 'Inherent Vice' (2014) — a more accessible work than 'Gravity's Rainbow.' 'Gravity's Rainbow' won the National Book Award (1974) but was notably rejected by the Pulitzer Prize judges who deemed it incomprehensible. PTA's Best Picture Oscar 2026 triumph represented vindication of translating notoriously difficult literature into cinema. The adaptation's success affirmed visionary directing can make literary complexity cinematically accessible. Pynchon's literary status achieved mainstream recognition through film adaptation, exemplifying how cinema extends literary influence beyond academic circles. The Oscar validated both Pynchon's vision and Anderson's directorial artistry in bridging literature and film.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23057,"question_text":"'Avatar: Fire and Ash' won Best Visual Effects at the 98th Oscars 2026. This is which entry in the Avatar franchise?","option_a":"Second (Avatar 2)","option_b":"Third (Avatar 3)","option_c":"Fourth (Avatar 4)","option_d":"First prequel","correct_answer":"B","explanation":"'Avatar: Fire and Ash' (James Cameron, 2026) is the third film in the Avatar franchise — following 'Avatar' (2009, won Academy Award for Best Visual Effects) and 'Avatar: The Way of Water' (2022, won Best Visual Effects). The Avatar franchise has won the Best Visual Effects Oscar three consecutive times across three decades (2010, 2023, 2026) — an unprecedented achievement demonstrating Cameron's sustained innovation in VFX technology. 'Avatar' (2009) remains the highest-grossing film of all time globally (~$2.9 billion), establishing an unparalleled commercial benchmark. 'Avatar: Fire and Ash' expands the Pandora world-building to explore new biomes including fire environments, volcanic regions, and challenging ecological systems. Cameron's continued VFX innovation demonstrates how blockbuster cinema can simultaneously achieve commercial dominance and technical artistry. The franchise's multiple VFX wins validate Hollywood's commitment to visual spectacle as essential cinema craft. Avatar's 2026 VFX victory affirmed 15+ years of sustained technological advancement and artistic vision.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23058,"question_text":"'Frankenstein' won 3 Oscars at the 98th ceremony (2026) in which craft categories?","option_a":"Best VFX, Best Sound, Best Score","option_b":"Best Costume Design, Best Makeup & Hairstyling, Best Production Design","option_c":"Best Cinematography, Best Editing, Best Score","option_d":"Best VFX, Best Costume Design, Best Film Editing","correct_answer":"B","explanation":"'Frankenstein' achieved a craft sweep at the 98th Academy Awards (2026) winning three prestigious design Oscars: Best Costume Design + Best Makeup and Hairstyling + Best Production Design. These interconnected craft categories typically honour period films and monster films featuring elaborate visual design, intricate costuming, and historically accurate or fantastical production environments. 'Frankenstein's trio of wins reflected the film's comprehensive commitment to historical costume authenticity, makeup artistry creating character authenticity, and production design establishing visual world-building. These categories recognise the invisible artisanal work enabling cinematic immersion. Comparative 98th Oscars craft winners: 'Avatar: Fire and Ash' won Best Visual Effects; 'Sinners' won Best Cinematography and Best Film Editing. The craft Oscar distribution demonstrated how multiple films excel in distinct technical specialisations, validating comprehensive excellence across filmmaking dimensions.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23059,"question_text":"The 97th Oscars (March 2025) Best Picture was 'Anora' — directed by Sean Baker. Which actress won Best Actress for this film?","option_a":"Demi Moore","option_b":"Fernanda Torres","option_c":"Mikey Madison","option_d":"Cynthia Erivo","correct_answer":"C","explanation":"97th Academy Awards (March 2025): Best Picture: 'Anora' (Sean Baker) — a contemporary drama sweeping five major categories. Best Actress: Mikey Madison — for her transformative role as Anora, a New York City sex worker who unexpectedly marries the son of a Russian oligarch, leading to hilarious and dramatic complications. 'Anora' swept 5 Oscars: Best Picture, Best Director (Sean Baker), Best Actress (Mikey Madison), Best Original Screenplay (Sean Baker), and Best Supporting Actor. Madison's Oscar victory validated her versatility — she is also known for 'Scream' (2022) and 'Scream VI' (2023) playing antagonist Amber Freeman. 'Anora' represented American independent cinema achieving major studio recognition. Sean Baker's directorial achievement demonstrated how contemporary comedic-dramatic scripts about everyday characters achieve critical acclaim. Madison's Oscar affirmed her emergence as major American actress. The film's success preceded the 98th Oscars (March 2026), where 'One Battle After Another' won Best Picture, continuing a pattern of acclaimed American cinema achievement.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23060,"question_text":"Adrien Brody won Best Actor at the 97th Oscars 2025 for which film, his second Best Actor Oscar?","option_a":"The Zone of Interest","option_b":"The Brutalist","option_c":"A Complete Unknown","option_d":"Emilia Pérez","correct_answer":"B","explanation":"97th Academy Awards (March 2025): Best Actor: Adrien Brody for 'The Brutalist' (directed by Brady Corbet) — playing a Hungarian-Jewish architect Laszlo Tóth who flees post-WWII Europe to America seeking artistic freedom and professional opportunities. This represents Brody's SECOND Best Actor Oscar, following his earlier win for 'The Pianist' (2002) — which made him the youngest Best Actor winner at age 29 at that time. 'The Brutalist' is an ambitious 3.5-hour epic exploring post-war American immigrant experience, architectural vision, and artistic integrity amid capitalist pressures. Brody's dual Best Actor Oscars position him among cinema's most celebrated dramatic actors. He also won BAFTA and Golden Globe for the same 'Brutalist' role, validating international critical consensus. His Oscar trajectory demonstrates sustained excellence spanning two decades. Brody's 2025 Oscar represented recognition of career evolution and mature dramatic range. 'The Brutalist's success validated contemporary ambitious filmmaking — long-form narrative epics achieving critical and commercial recognition.","folder":"AP_HC","topic":"International_Current_Affairs"},

    # ── Padma Awards 2026 (23061-23066) ──
    {"id":23061,"question_text":"Padma Awards 2026 announced on January 25, 2026 — how many total awards including the Padma Vibhushan, Bhushan and Shri?","option_a":"112","option_b":"119","option_c":"131","option_d":"144","correct_answer":"C","explanation":"Padma Awards 2026: Total 131 civilian honours (including 2 duo cases) announced January 25, 2026 (Republic Day eve): 5 Padma Vibhushan + 13 Padma Bhushan + 113 Padma Shri. Padma Awards represent India's highest civilian honours hierarchy: Bharat Ratna (India's supreme civilian award, only 120 total recipients in 76 years) > Padma Vibhushan (highest after Bharat Ratna) > Padma Bhushan (third) > Padma Shri (fourth). Awards are conferred by the President at Rashtrapati Bhavan ceremonial function. The 2026 Padma awards recognised exceptional contributions across sectors: sports, arts, science, public service, education, commerce, social work. The 131 awardees represented diverse India — 16 posthumous awards, 19 women recipients, 6 foreigners/NRIs/PIOs/OCIs. The awards reflect India's recognition of global and national excellence. Padma Awards embody India's soft power — honouring individuals who've contributed to global causes, Indian cultural promotion, scientific advancement, humanitarian work.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23062,"question_text":"Which legendary Bollywood actor received Padma Vibhushan (posthumously) in Padma Awards 2026?","option_a":"Rishi Kapoor","option_b":"Dharmendra Singh Deol","option_c":"Dilip Kumar","option_d":"Rajesh Khanna","correct_answer":"B","explanation":"Padma Vibhushan 2026 (posthumous): Dharmendra Singh Deol — legendary 'He-Man of Bollywood' whose career spanning 60+ years defined Hindi cinema masculinity and action cinema. Known for iconic films: 'Sholay' (1975, seminal action-drama), 'Phool Aur Patthar' (1966, romantic drama), 'Satyakam' (1969). Dharmendra became Bollywood's most bankable action star, beloved across generations. Posthumous recognition at age ~89 honoured his immense cinematic legacy. Also receiving Padma Vibhushan posthumously: VS Achuthanandan (former Kerala CM, CPI-M veteran, died 2025, pioneered land reforms). The 2026 Padma Vibhushan recognising cinema legends (Dharmendra) and political stalwarts (Achuthanandan) demonstrated India's commitment honouring diverse contributions across sectors. Dharmendra's Padma Vibhushan represented Bollywood's global cultural significance and soft power. His career influenced generations of filmmakers and actors, establishing action cinema traditions. The posthumous award affirmed that Bollywood excellence merits India's highest civilian honours recognising artistic contribution to national culture and global entertainment prominence.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23063,"question_text":"Vijay Amritraj received Padma Bhushan 2026. He is a legendary Indian sportsperson in which field?","option_a":"Cricket","option_b":"Badminton","option_c":"Tennis","option_d":"Squash","correct_answer":"C","explanation":"Vijay Amritraj received Padma Bhushan 2026 — India's third-highest civilian honour — recognising his legendary contributions to tennis. Amritraj achieved world No. 18 ranking during tennis's Open Era (1970s-80s), representing India in Davis Cup competitions spanning over two decades, elevating India's tennis profile globally. He was a pioneering Indian male tennis professional competing at Wimbledon, US Open, French Open, and Australian Open — major global tournaments. Amritraj's international career preceded contemporary Indian tennis excellence (Sania Mirza, Nagal). He also appeared in James Bond film 'Octopussy' (1983) as a minor character, demonstrating Hindi cinema-international crossover. Padma Bhushan 2026 honouring Amritraj recognised sporting excellence and India's international tennis representation. Other Padma Shri 2026 recipients: Rohit Sharma (cricket, India's test captain), Harmanpreet Kaur (women's cricket captain), Savita Punia (women's hockey goalkeeper). The 2026 Padma awards recognising contemporary sports leaders (Sharma, Kaur, Punia) alongside historic figures (Amritraj) demonstrated India's institutional appreciation for sporting excellence across eras. Amritraj's Padma Bhushan represented recognition of his trailblazing role in establishing professional tennis in India.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23064,"question_text":"VS Achuthanandan, who received Padma Vibhushan 2026 posthumously, served as Chief Minister of which Indian state?","option_a":"Tamil Nadu","option_b":"Karnataka","option_c":"Kerala","option_d":"Andhra Pradesh","correct_answer":"C","explanation":"VS Achuthanandan (initials for Vazhappally Sreedharan) — posthumously awarded Padma Vibhushan 2026 — served as Chief Minister of Kerala (2006-2011). Born 1923, died 2025 at age 101+, representing one of India's longest-lived political veterans. Achuthanandan was a legendary CPI(M) leader dedicated to communist movement for over 70 years, embodying Indian Left's commitment. Known for anti-corruption stance (particularly during his CM tenure fighting white-collar crime), personal simplicity, and grassroots connection. Instrumental in Kerala's land reforms redistributing agricultural land to landless peasants — a transformative policy. His governance emphasised education, healthcare access, and social equity — hallmarks of Kerala's developmental model. Achuthanandan represented Kerala communism's intellectual tradition combining Marxist ideology with democratic practice. His posthumous Padma Vibhushan honoured his extraordinary contribution to Indian Left movement and Kerala's progressive governance. His longevity (101 years) enabled him to witness Indian independence through 21st century, bridging colonial and contemporary India. VS Achuthanandan exemplified democratic communism's commitment to social justice through electoral politics.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23065,"question_text":"Cricket captain Rohit Sharma received which Padma Award in 2026?","option_a":"Padma Vibhushan","option_b":"Padma Bhushan","option_c":"Padma Shri","option_d":"Bharat Ratna","correct_answer":"C","explanation":"Rohit Sharma (India's Test and ODI captain) received Padma Shri 2026 — India's fourth-highest civilian honour recognising sporting excellence. Padma Shri honours represent India's appreciation for substantial contributions across diverse sectors. Rohit Sharma's leadership of Indian cricket across multiple formats represents extraordinary responsibility — captaining billions of supporters. Also receiving Padma Shri 2026: Harmanpreet Kaur (India women's cricket captain) — championing women's cricket visibility and participation. Savita Punia (India women's hockey goalkeeper) — crucial to India's hockey renaissance. The 2026 Padma awards recognising contemporary sports leaders represented India's institutional commitment to athletic excellence. Vijay Amritraj received Padma Bhushan (tennis), while Dharmendra and VS Achuthanandan received Padma Vibhushan (both posthumous). The sporting trio (Rohit, Harmanpreet, Savita) receiving Padma Shri simultaneously demonstrated India's multi-sport excellence recognition — beyond traditional cricket dominance. Their awards validated women's sports parity with men's sports in national honours systems. Rohit Sharma's Padma Shri affirmed cricket captaincy as prestigious national service meriting highest civilian recognition.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23066,"question_text":"The last batch of Bharat Ratna awards was conferred in 2024 on five personalities. Which of the following was NOT among them?","option_a":"LK Advani (former Deputy PM)","option_b":"Karpoori Thakur (posthumous, former Bihar CM)","option_c":"MS Swaminathan (posthumous, Green Revolution)","option_d":"Ratan Tata (posthumous, Tata Group)","correct_answer":"D","explanation":"Bharat Ratna 2024 batch (final five awardees): LK Advani (living, BJP founder/former Deputy PM); Karpoori Thakur (posthumous, former Bihar CM, OBC reservation pioneering); PV Narasimha Rao (posthumous, former PM, liberalisation architect); MS Swaminathan (posthumous, Green Revolution father, agricultural scientist); Chaudhary Charan Singh (posthumous, former PM, farmers' advocate). NO Bharat Ratna has been awarded in 2025 or 2026 to date. Ratan Tata (Tata Group patriarch, died October 2024) was notably NOT conferred Bharat Ratna despite extensive public demands and nationwide mourning. Ratan Tata's exclusion prompted national debate about Bharat Ratna selection criteria despite his extraordinary business achievements, philanthropic contributions (Tata Trusts), and industrial legacy. Bharat Ratna represents India's highest civilian honour — only 120 total recipients in independent India's 76-year history. The 2024 award to PV Narasimha Rao (previously controversial as PM) represented rehabilitated historical assessment. MS Swaminathan's Green Revolution legacy connected agricultural modernisation to national food security. The 2024 batch reflected India's commitment honouring diverse excellence across politics, agriculture, and nation-building.","folder":"AP_HC","topic":"International_Current_Affairs"},

    # ── Other Notable 2025-2026 Awards (23067-23080) ──
    {"id":23067,"question_text":"The Abel Prize 2025 (mathematics' equivalent of Nobel) was awarded to which Japanese mathematician for D-module theory?","option_a":"Masaki Izumi","option_b":"Masaki Kashiwara","option_c":"Shigeru Mochizuki","option_d":"Hideo Kojima","correct_answer":"B","explanation":"Abel Prize 2025: Masaki Kashiwara (Japan, Research Institute for Mathematical Sciences, Kyoto University) — awarded for extraordinary contributions to D-module theory and the Riemann-Hilbert correspondence. Kashiwara made this the first Abel Prize for a Japanese mathematician — representing Japan's mathematical excellence globally. D-modules represent sophisticated algebraic structures linking differential equations to representation theory and harmonic analysis — abstract mathematics with profound theoretical implications. The Riemann-Hilbert correspondence connects differential equations to topological invariants — foundational to modern mathematics. The Abel Prize, awarded by the Norwegian Academy of Science and Letters with NOK 7.5 million (~$700,000 USD), represents mathematics's highest honour equivalent to Nobel Prize (Nobel excluded mathematics until Economics Prize creation 1968). Kashiwara's recognition affirmed Japanese mathematics tradition alongside established European/American dominance. Abel Prize 2024: Michel Talagrand (France) for probability theory. Kashiwara's 2025 award represented international mathematics recognising Asian theoretical contributions — reflecting globalised research communities transcending geographic boundaries.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23068,"question_text":"The Pritzker Architecture Prize 2025 — architecture's highest honour — was awarded to which Chinese architect?","option_a":"Ma Yansong","option_b":"Wang Shu","option_c":"Liu Jiakun","option_d":"Zhu Pei","correct_answer":"C","explanation":"Pritzker Architecture Prize 2025: Liu Jiakun (China) — the first Chinese national architect to win since Wang Shu's 2012 award. Liu Jiakun is renowned for community-centred architecture philosophy balancing cultural tradition with contemporary modernity. His work emphasises participatory design — engaging communities in built environment creation. He led significant post-earthquake reconstruction efforts in Sichuan Province following the devastating 2008 earthquake that killed 70,000+ people. His earthquake reconstruction designs demonstrated architecture's humanitarian dimensions — rebuilding homes and community facilities addressing both physical and psychological recovery. The Pritzker Architecture Prize, awarded by the Hyatt Foundation with $100,000 prize purse, represents architecture's highest international honour — frequently called 'architecture's Nobel Prize.' Liu Jiakun's win validated contemporary Chinese architecture's global significance and humanitarian commitment. His award recognised how non-Western architectural traditions address community needs through culturally-responsive design. China's representation in Pritzker (Wang Shu 2012, Liu Jiakun 2025) demonstrated Asia's architectural leadership challenging Western-centric design hierarchies.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23069,"question_text":"India's 75th Dadasaheb Phalke Award (conferred September 23, 2025) was awarded to which legendary actor — the FIRST Malayalam cinema actor to receive this honour?","option_a":"Mammootty","option_b":"Kamal Haasan","option_c":"Mohanlal","option_d":"Rajinikanth","correct_answer":"C","explanation":"75th Dadasaheb Phalke Award (September 23, 2025): Mohanlal Viswanathan — historic achievement as the FIRST Malayalam cinema actor to win India's highest film honour, awarded by the President. Mohanlal's career spanned 360+ films across Malayalam, Tamil, Telugu, Kannada, and Hindi cinema over 40+ years — representing pan-Indian cinema excellence. He is beloved across language communities, transcending regional boundaries — a hallmark of truly national stardom. Known for landmark films: 'Kireedam' (1989, crime drama), 'Bharatham' (1991, family drama), 'Drishyam' (2013, thriller), 'Lucifer' (2019, action). His award recognised Malayalam cinema's evolution as major Indian film industry alongside Hindi, Tamil, Telugu cinemas. Previous Dadasaheb Phalke winners: Waheeda Rehman (2021, awarded 2023), Mithun Chakraborty (2022), Asha Parekh (2020, awarded 2024). The 75th Dadasaheb Phalke award affirmed regional Indian cinema's legitimacy — validating Malayalam, Kannada, Tamil industries as essential to Indian film heritage. Mohanlal's award represented India's commitment recognising pan-Indian cinema excellence transcending Hindi hegemony.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23070,"question_text":"The Ramon Magsaysay Award — often called 'Asia's Nobel Prize' — is presented by which country?","option_a":"Japan","option_b":"South Korea","option_c":"Philippines","option_d":"Thailand","correct_answer":"C","explanation":"Ramon Magsaysay Award is presented in Manila, Philippines — Asia's premier civil society honour named after Philippine President Ramon Magsaysay (1907-1957, died in plane crash during presidency). Awarded annually to individuals/organisations demonstrating exceptional Asian leadership across six categories: government service, public service, community leadership, journalism, literature/creative arts, peace/international understanding. Prize: $50,000 USD. Headquarters: Ramon Magsaysay Award Foundation, Manila. India has received substantial recognition: 2025 winner Educate Girls (first Indian organisation to win). Previous Indian winners: Vinoba Bhave (1958, first-ever), Mother Teresa (1962), Kailash Satyarthi (child rights), Arvind Kejriwal (governance), among others. The award represents Asia's commitment recognising transformative leadership addressing continental challenges. Ramon Magsaysay Award's 'Asia's Nobel Prize' designation reflects its prestige within Asian civil society — comparable to Nobel internationally. The award validates Indian changemakers' contributions to regional development and humanitarian progress.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23071,"question_text":"The ACM A.M. Turing Award 2025 (announced March 2026) was awarded to Charles H. Bennett (IBM) and Gilles Brassard (Université de Montréal) for founding which field?","option_a":"Artificial general intelligence (AGI)","option_b":"Quantum information science and quantum cryptography","option_c":"Distributed ledger / blockchain","option_d":"Computer graphics and rendering","correct_answer":"B","explanation":"ACM A.M. Turing Award 2025 (announced March 2026): Charles H. Bennett (IBM Research) and Gilles Brassard (Université de Montréal) — recognised for establishing quantum information science and quantum cryptography foundations. Their 1984 BB84 protocol launched quantum key distribution (QKD) — enabling theoretically unbreakable communication using quantum mechanics properties. Quantum information science represents 21st-century computing frontier addressing classical computing limitations through quantum phenomena (superposition, entanglement, interference). Their work transformed secure communication paradigms — critical amid contemporary cybersecurity threats. The Turing Award carries $1 million prize (Google-sponsored), representing computer science's highest honour equivalent to Nobel Prize. India recognises quantum computing's significance (IIT Delhi, TIFR launching quantum centres), validating Bennett/Brassard's foundational contributions reshaping global computing infrastructure. Turing Award 2024: Andrew Barto and Richard Sutton (reinforcement learning). Bennett and Brassard's 2025 recognition affirmed quantum computing's centrality to 21st-century technological transformation and cybersecurity paradigm shifts.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23072,"question_text":"The FIFA Best Men's Player Award 2025 was won by the same player as the Ballon d'Or 2025. Who was it?","option_a":"Erling Haaland","option_b":"Vinicius Jr","option_c":"Ousmane Dembélé","option_d":"Kylian Mbappé","correct_answer":"C","explanation":"FIFA Best Men's Player 2025: Ousmane Dembélé (PSG) — consistent with Ballon d'Or 2025 win reflecting PSG's historic 2024-25 quadruple (Ligue 1, Coupe de France, UEFA Champions League, domestic cup). FIFA awards validate multiple international bodies' assessment of player excellence. FIFA Best Women's Player 2025: Aitana Bonmatí (FC Barcelona) — third consecutive win. FIFA Best Coach 2025: Luis Enrique (PSG, managing quadruple-winning team). FIFA Best Goalkeeper 2025: Gianluigi Donnarumma (PSG). FIFA Best Awards (January 2026, Zurich) represent international football governance's recognition of player/coach excellence. Dembélé's dual-award victories (Ballon d'Or, FIFA Best) affirmed universal consensus on his transformative 2024-25 season. The awards highlight PSG's historic achievement — previously considered a perennial underachiever in European football. Dembélé's recognition validated his transfer impact and demonstrated how individual excellence contributes to collective championship success.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23073,"question_text":"The Sakharov Prize 2025 (European Parliament's human rights prize) was awarded to defenders of which country's 'Woman, Life, Freedom' movement?","option_a":"Russia","option_b":"Iran","option_c":"Myanmar","option_d":"Afghanistan","correct_answer":"B","explanation":"Sakharov Prize 2025 (European Parliament): Awarded to Iranian women human rights defenders of 'Woman, Life, Freedom' (Zan, Zendegi, Azadi) movement — sparked by Mahsa Amini's death in police custody September 2022. The movement represents grassroots resistance to gender-based oppression and authoritarian governance across Iran. Amini's death galvanised international attention to women's rights violations, inspiring sustained activism despite severe government repression. The Sakharov Prize for Freedom of Thought, awarded annually since 1988 with €50,000 prize, honours individuals/groups defending fundamental human rights and freedoms. Named after Soviet physicist Andrei Sakharov, the dissent champion who challenged USSR authoritarianism. The prize's selection of Iranian women activists recognised contemporary human rights struggles and female leadership in freedom movements. The award validated grassroots activism against oppressive governance systems. Women's human rights defenders globally (including India's anti-violence activists) recognised the prize's significance validating gender equality struggles transcending geographic/political boundaries.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23074,"question_text":"The Booker Prize 2025 winner David Szalay was previously shortlisted for which earlier novel?","option_a":"Spring","option_b":"London and the South-East","option_c":"All That Man Is","option_d":"The Innocent","correct_answer":"C","explanation":"David Szalay was Booker Prize shortlisted for 'All That Man Is' (2016) — a multi-narrative novel of nine interconnected stories exploring European men across different life stages. In 2025, he won the Booker Prize for 'Flesh' — his breakthrough victory as the first Hungarian-British author to win. Szalay is a British-Canadian author of Hungarian descent, born in Montreal, raised in London. He writes sparse, philosophical English-language fiction exploring masculinity, class, and existential themes. His previous shortlisting (2016) and 2025 victory represent sustained literary excellence and evolving recognition. Szalay's Booker win validated philosophical fiction addressing human vulnerability. His success alongside Nobel Literature 2025 winner László Krasznahorkai (Hungarian) made 2025 a landmark year for Hungarian letters globally.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23075,"question_text":"Percival Everett, who won Pulitzer Prize 2025 for Fiction ('James'), is also a professor at which US university?","option_a":"Yale University","option_b":"University of Southern California (USC)","option_c":"Columbia University","option_d":"Howard University","correct_answer":"B","explanation":"Percival Everett is Distinguished Professor of English at University of Southern California (USC) — a major research institution. His Pulitzer-winning 'James' (2024) retells 'Adventures of Huckleberry Finn' from enslaved Jim's perspective, demonstrating how contemporary American fiction revises canonical texts through marginalised voices. Everett is extraordinarily prolific — over 30 books spanning literary fiction, science fiction, satire. His body of work demonstrates intellectual range and social consciousness. 'James' won multiple major prizes: Pulitzer Prize 2025, PEN/Faulkner Award, Carnegie Medal for Excellence in Fiction, Kirkus Prize — unprecedented sweep validating exceptional literary achievement. Everett's academic position at USC enables mentorship of emerging writers while maintaining prolific authorship. His 2025 Pulitzer recognition elevated him to American literary canon's highest reaches. His achievement represented contemporary Black American letters achieving dominant cultural and institutional recognition.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23076,"question_text":"Maria Corina Machado (Nobel Peace 2025) leads which Venezuelan political party/movement?","option_a":"Democratic Action (AD)","option_b":"Vente Venezuela","option_c":"Popular Will (Voluntad Popular)","option_d":"Justice First (Primero Justicia)","correct_answer":"B","explanation":"Maria Corina Machado leads 'Vente Venezuela' (Come Venezuela) — a political movement/party she founded in 2012 representing democratic opposition. She was barred from holding public office by Maduro government despite winning 2024 opposition presidential primary with overwhelming support — demonstrating authoritarian suppression. Nobel Peace Prize 2025 recognition honoured her non-violent democratic resistance against Nicolás Maduro's 25-year authoritarian rule. Venezuela's humanitarian crisis has displaced over 7.7 million refugees globally — one of contemporary world's worst humanitarian catastrophes. Venezuelan diaspora communities exist across Latin America, North America, and Asia (including India). Machado represents contemporary democratic defenders worldwide facing authoritarian suppression. Her Nobel win validated international solidarity with Venezuelan civil society resistance. The award signified how international honours amplify silenced voices and document authoritarian abuses. Machado's struggle exemplifies global patterns of electoral fraud, judicial corruption, and democratic erosion in authoritarian regimes.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23077,"question_text":"The Golden Globe for Best Original Song went to 'Golden' from 'KPop Demon Hunters' at the 83rd Globes (Jan 2026). This song later also won the Oscar. Who performed it?","option_a":"BTS","option_b":"BLACKPINK","option_c":"The film's fictional K-pop group performed by real K-pop artists","option_d":"NCT Dream","correct_answer":"C","explanation":"'Golden' from 'KPop Demon Hunters' (2026) achieved historic sweep winning Best Original Song at 83rd Golden Globes (January 2026) and 98th Oscars (March 2026). The animated film features a fictional K-pop group whose music was created collaboratively with real K-pop producers and artists — integrating authentic Korean music industry expertise into Hollywood production. Sony Pictures Animation's 'KPop Demon Hunters' swept animated categories: Best Animated Feature + Best Original Song at 98th Oscars, establishing dominance in animation awards. The film exemplifies contemporary Hollywood-Korean entertainment industry collaboration. K-pop's global influence (BTS, BLACKPINK establishing international fanbases) enabled soundtrack's cultural resonance. 'Golden' became streaming phenomenon globally. The awards validated K-pop's legitimate place in mainstream entertainment recognition beyond fandom enthusiasm. The song's Oscar victory represented cultural diplomacy — Korean artistic traditions achieving validation within Western institutional honours.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23078,"question_text":"The 2025 Ballon d'Or Best Coach Award went to which England Women's national team coach?","option_a":"Pep Guardiola","option_b":"Carlo Ancelotti","option_c":"Sarina Wiegman","option_d":"Luis Enrique","correct_answer":"C","explanation":"Ballon d'Or 2025 Best Coach: Sarina Wiegman (Netherlands) — England Women's national team head coach. Wiegman's achievements: 2022 UEFA Women's Euro title (Lionesses' historic first major trophy), 2023 Women's World Cup final appearance. She maintains exemplary competitive record as England coach. FIFA Best Women's Coach 2025 also honoured Wiegman — dual recognition validating exceptional coaching excellence. Wiegman represents contemporary women's football's elevation through professional coaching infrastructure. Her England team achieved unprecedented visibility and support through Euros 2022 triumph. Women's football's growth under coaches like Wiegman demonstrated gender equity progress in sports. Wiegman's Ballon d'Or recognition alongside men's coaches (Guardiola, Ancelotti, Enrique) affirmed parity in institutional awards systems. Her success established women's football coaching as equivalent professional discipline to men's elite coaching. The award validated women's sports excellence and coaching merit transcending gender hierarchies in athletic recognition.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23079,"question_text":"The Indira Gandhi Prize for Peace, Disarmament and Development 2025 was awarded to which Mozambican women's-rights activist (widow of Nelson Mandela)?","option_a":"Michelle Bachelet","option_b":"Graça Machel","option_c":"Ellen Johnson Sirleaf","option_d":"Leymah Gbowee","correct_answer":"B","explanation":"Indira Gandhi Prize for Peace, Disarmament and Development 2025: Graça Machel (Mozambique) — selected by international jury chaired by former National Security Advisor Shivshankar Menon. Machel's recognition honoured path-breaking contributions: education access, health/nutrition programmes, women's economic empowerment, humanitarian work amid conflict. She is widow of anti-apartheid hero Nelson Mandela and former Mozambique Foreign Minister. Her work bridged anti-colonial struggle legacy to contemporary development activism. Prize: Rs 1 crore and citation. The award validated women humanitarian leaders addressing development across African continent. Graça Machel represents African women's leadership transcending spousal identity — recognised independently for exceptional humanitarian contributions. India's Indira Gandhi Prize affirmed global development consciousness and women's rights recognition. IG Peace Prize 2024: Michelle Bachelet (former Chile President, awarded November 20, 2025). The annual prize honours Indira Gandhi's legacy promoting peace and disarmament globally.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23080,"question_text":"The Academy Awards ceremony for the 98th Oscars (March 2026) — where 'One Battle After Another' won Best Picture — was held at which venue?","option_a":"Dolby Theatre, Hollywood","option_b":"Kodak Theatre, Hollywood","option_c":"The Shrine Auditorium, Los Angeles","option_d":"TCL Chinese Theatre, Hollywood","correct_answer":"A","explanation":"98th Oscars ceremony (March 2026): Dolby Theatre, Hollywood, Los Angeles — the ceremony's permanent venue since 2002. Previously called Kodak Theatre (renamed Dolby Laboratory Cinemark Theatre in 2012). The Dolby Theatre's Hollywood location symbolises the awards ceremony's connection to entertainment industry's historic centre. Hosted by Conan O'Brien — marking his return to major host responsibilities. Academy of Motion Picture Arts and Sciences (AMPAS) presents the annual Oscars recognising cinema excellence. The Dolby Theatre's 3,400-seat capacity enables intimate ceremony broadcasting to billions globally. 98th Oscars' 'One Battle After Another' Best Picture victory occurred at this prestigious venue. The ceremony venue's consistency (since 2002) provides institutional continuity while Dolby naming represents corporate sponsorship reality of contemporary awards shows. The venue's Hollywood location maintains Oscar's cultural association with entertainment industry's geographic epicentre.","folder":"AP_HC","topic":"International_Current_Affairs"},

    # ── 2025-26 Freshness Gap-Fill (23081-23092) ──
    {"id":23081,"question_text":"Time magazine's 2025 Person of the Year was a collective titled what — featuring tech leaders including Sam Altman, Jensen Huang, Demis Hassabis and Fei-Fei Li?","option_a":"The Climate Defenders","option_b":"The Architects of AI","option_c":"The Quantum Pioneers","option_d":"The Mars Generation","correct_answer":"B","explanation":"Time Person of the Year 2025: 'The Architects of AI' — individuals who imagined, designed, built artificial intelligence reshaping human civilization. The cover featured: Mark Zuckerberg (Meta), Elon Musk (Tesla/xAI), Jensen Huang (NVIDIA CEO, AI chips), Sam Altman (OpenAI CEO, ChatGPT), Demis Hassabis (Google DeepMind, AlphaFold), Lisa Su (AMD CEO, semiconductors), Dario Amodei (Anthropic CEO, alignment research), Fei-Fei Li (Stanford AI lab, ethics). Time recognised individual agency rather than AI technology itself, noting 2025 as the year AI's transformative potential 'roared into view.' The selection reflected global recognition of AI's accelerating impact on economies, societies, governance, science, creative industries. Time POY 2024: Donald Trump (second-time POY). The 2025 selection affirmed technology leaders' institutional power shaping global futures. India's increasing AI investment (Infosys, TCS AI initiatives) validates global AI centrality to development narratives.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23082,"question_text":"The Earthshot Prize 2025 — Prince William's £1 million-per-winner environmental award — was hosted in which city on November 5, 2025?","option_a":"Singapore","option_b":"Cape Town, South Africa","option_c":"Rio de Janeiro, Brazil","option_d":"Boston, USA","correct_answer":"C","explanation":"Earthshot Prize 2025: Awards ceremony Rio de Janeiro, Brazil, November 5, 2025 — selecting winners from 2,500 nominations across 72 countries addressing climate, biodiversity, ocean, air quality, waste challenges. Five winners, £1 million each: (1) re.green — Brazilian Atlantic Forest/Amazon restoration; (2) Bogotá city government — urban clean air/transport transformation; (3) High Seas Treaty — global ocean governance (enters force January 2026 post 60th ratification); (4) Friendship Bangladesh (Runa Khan's conservation NGO); (5) Lagos Fashion Week Nigeria (sustainable fashion). Founded by Prince William (2020), the prize represents British royal family's environmental advocacy. Rio de Janeiro venue symbolised Brazil's climate leadership and conservation importance. The award recognised diverse environmental solutions spanning reforestation, urban sustainability, ocean protection, fashion innovation, civil society organising. India's conservation leaders eligible globally; Indian NGOs increasingly recognised for environmental stewardship. The Earthshot Prize exemplifies how institutional wealth mobilises global environmental action across developing nations.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23083,"question_text":"The 2025 Templeton Prize (~$1.5 million, for harmonising science and spirituality) was awarded to which spiritual leader of 300 million Eastern Orthodox Christians?","option_a":"Pope Francis","option_b":"Dalai Lama","option_c":"Ecumenical Patriarch Bartholomew","option_d":"Archbishop of Canterbury","correct_answer":"C","explanation":"Templeton Prize 2025: Ecumenical Patriarch Bartholomew of Constantinople — spiritual leader of ~300 million Eastern Orthodox Christians (Constantinople Patriarchate second-oldest Christian institution, founded 330 AD). Bartholomew earned the epithet 'Green Patriarch' through three decades of environmental theology integrating ecological stewardship into Christian spirituality — linking faith to environmental responsibility. He received the prize at September 24, 2025 ceremony at Lincoln Center, New York City. The Templeton Prize, established 1972, awards approximately $1.5 million USD — exceeding Nobel Prize monetary value. It recognises work harmonising science and spirituality, addressing intersection of material world understanding and transcendent meaning-making. Templeton Prize's global recognition affirms Eastern Orthodox Christianity's intellectual contributions to contemporary theological discourse. Patriarch Bartholomew's environmental theology influenced global Christian environmental ethics. His recognition validated interfaith dialogue and spiritual leadership addressing climate change through religious frameworks. The award represented how traditional religions contribute to global sustainability discourse.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23084,"question_text":"The World Food Prize 2025 was awarded to Brazilian microbiologist Dr. Mariangela Hungria for pioneering work in which agricultural innovation?","option_a":"Genetically modified drought-resistant maize","option_b":"Biological nitrogen fixation using soil bacteria","option_c":"Precision drip irrigation","option_d":"Vertical farming techniques","correct_answer":"B","explanation":"World Food Prize 2025: Dr. Mariangela Hungria (Brazil) — for transformative work developing biological nitrogen fixation alternatives to synthetic fertilisers. She developed dozens of biological seed and soil treatments using symbiotic soil microorganisms (rhizobia bacteria, azospirillum) to naturally fix atmospheric nitrogen into soil-available form. These sustainable alternatives reduced synthetic fertiliser dependency across 40+ million hectares in Brazil — saving farmers ~US$40 billion annually and preventing 180+ million metric tons CO2-equivalent emissions yearly. Her innovations made Brazil an agricultural superpower while advancing sustainability. The World Food Prize (founded 1987, headquartered Des Moines, Iowa) represents agriculture's highest honour. Hungria's recognition validated how microbiology addresses global food security and climate change simultaneously. Biological nitrogen fixation represents sustainable agriculture paradigm shift from petroleum-dependent synthetic fertilisers. Her work benefited developing nations (including India) transitioning toward sustainable farming. The award exemplified how agricultural science directly addresses poverty, hunger, and environmental sustainability globally.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23085,"question_text":"The Right Livelihood Award 2025 (called the 'Alternative Nobel') honoured which Taiwanese digital democracy minister among its laureates?","option_a":"Tsai Ing-wen","option_b":"Audrey Tang","option_c":"Joshua Wong","option_d":"Nathan Law","correct_answer":"B","explanation":"Right Livelihood Award 2025 ('Alternative Nobel' honouring courageous social justice leaders): Four laureates: (1) Audrey Tang (Taiwan) — for advancing digital technology toward citizen empowerment, democratic renewal, and social healing (former Digital Minister); (2) Emergency Response Rooms (Sudan) — mutual aid networks providing relief amid catastrophic civil war; (3) Justice for Myanmar — investigative collective exposing international corporate complicity sustaining military junta; (4) Pacific Islands Students Fighting Climate Change (PISFCC) & Julian Aguon — climate justice advocacy bringing island nations' cases to International Court of Justice. Ceremony: December 2, 2025, Stockholm. Right Livelihood Award, founded 1980, recognises grassroots activists addressing human rights, environmental justice, sustainable development. Audrey Tang represents contemporary digital governance innovation — using technology for transparency and participatory democracy. The award validated non-governmental actors challenging power structures and advocating justice.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23086,"question_text":"The Indira Gandhi Peace Prize 2024 (awarded November 20, 2025) was conferred on which former Chilean President and UN Human Rights High Commissioner?","option_a":"Cristina Fernández","option_b":"Michelle Bachelet","option_c":"Dilma Rousseff","option_d":"Verónica Michelle","correct_answer":"B","explanation":"Indira Gandhi Peace Prize 2024: Michelle Bachelet (Chile) — former President (two terms: 2006-2010, 2014-2018) and UN High Commissioner for Human Rights (2018-2022). Honoured November 20, 2025 for lifelong commitment to human rights, gender equality, women's/children's social protection, and global peace advocacy. Bachelet trained as paediatrician before political career — combining medical ethics with human rights commitment. Her double presidency represented Latin American women's political empowerment. Her UN tenure elevated human rights globally during authoritarian resurgence. The award recognised her principled leadership defending marginalised communities. Indira Gandhi Peace Prize 2025: Graça Machel (Mozambique). India's two-award recognition of women Latin American leaders (Bachelet 2024, Graça Machel 2025) demonstrated India's commitment validating women's humanitarian leadership globally, transcending geographic/political divisions.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23087,"question_text":"Banker Uday Kotak (founder, Kotak Mahindra Bank) received which Padma honour in 2026?","option_a":"Padma Vibhushan","option_b":"Padma Bhushan","option_c":"Padma Shri","option_d":"Bharat Ratna","correct_answer":"B","explanation":"Padma Awards 2026: Uday Kotak (Kotak Mahindra Bank founder/director) received Padma Bhushan — India's third-highest civilian honour in Trade and Industry category. Kotak represents Indian banking sector's modernisation and digital transformation. He served as Confederation of Indian Industry (CII) president, representing Indian business interests globally. His Padma Bhushan recognised contributions building world-class financial institution competing internationally. The 13 Padma Bhushan 2026 awardees included Kotak and tennis legend Vijay Amritraj — representing private sector and sports excellence. Padma Vibhushan 2026 (5 awardees): Dharmendra (posthumous, cinema), VS Achuthanandan (posthumous, politics), KT Thomas (judiciary), N. Rajam (music), P. Narayanan (education). The honours hierarchy (Vibhushan > Bhushan > Shri) recognised excellence across sectors. Kotak's Padma Bhushan validated Indian banking's institutional development and global competitiveness.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23088,"question_text":"Among the 5 Padma Vibhushan 2026 awardees, classical violinist Smt N. Rajam was honoured in which field?","option_a":"Public Affairs","option_b":"Art","option_c":"Literature and Education","option_d":"Science and Engineering","correct_answer":"B","explanation":"Padma Vibhushan 2026 (5 awardees, announced January 25, 2026): (1) Dharmendra (posthumous, Art — Bollywood); (2) VS Achuthanandan (posthumous, Public Affairs — former Kerala CM); (3) KT Thomas (Public Affairs — former Supreme Court judge); (4) Smt N. Rajam (Art — Hindustani classical violinist); (5) P. Narayanan (Literature and Education). Smt N. Rajam represents Indian classical music's global excellence — Hindustani violin tradition combining Indian raga structures with Western violin techniques. Her recognition affirmed classical music's institutional importance. Total Padma Awards 2026: 131 honours (5 Vibhushan + 13 Bhushan + 113 Shri); 16 posthumous; 19 women; 6 foreigners/NRI/PIO/OCI. The awards demonstrated India's institutional commitment recognising diverse excellence — cinema, classical music, judiciary, literature, sports, business, activism.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23089,"question_text":"Turing Award 2025 laureates Charles Bennett and Gilles Brassard are famous for their 1984 BB84 protocol. BB84 is the foundational protocol of which technology?","option_a":"Public-key cryptography (RSA)","option_b":"Quantum key distribution (QKD)","option_c":"Blockchain consensus","option_d":"Zero-knowledge proofs","correct_answer":"B","explanation":"Turing Award 2025 (Bennett & Brassard): Their 1984 BB84 protocol established foundational Quantum Key Distribution (QKD) — using quantum mechanics (photon polarisation encoding) to share encryption keys with mathematically provable security. Any eavesdropping attempt disturbs quantum state, immediately revealing compromise. QKD represents paradigm shift from computational security (RSA relies on factorisation difficulty, vulnerable to quantum computers) to fundamental quantum-physics-based security. QKD networks operationalise globally: China (Beijing-Shanghai quantum backbone), European Quantum Internet Alliance, satellite QKD (Micius Chinese satellite, 2017). Bennett (IBM Research) and Brassard (Université de Montréal) jointly founded quantum information science as discipline. Their 2025 Turing Award recognised decade-spanning impact reshaping cryptography and cybersecurity globally. India's emerging quantum research positions it to adopt QKD infrastructure — critical amid cybersecurity threats.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23090,"question_text":"Educate Girls (an Indian NGO) won the Ramon Magsaysay Award 2025 — what is the historical significance of this win?","option_a":"First-ever Magsaysay Award given to an Indian","option_b":"First Indian organisation (NGO) to win the Magsaysay Award","option_c":"Largest cash prize in Magsaysay history","option_d":"First all-women-led organisation to win","correct_answer":"B","explanation":"Ramon Magsaysay Award 2025: Educate Girls (India) achieved historic distinction as the FIRST INDIAN ORGANISATION (NGO) to win the Magsaysay Award. This grassroots NGO has enrolled thousands of out-of-school girls in classrooms across India's most underserved villages — addressing gender inequality in education access. Education represents foundational development indicator; girls' education particularly critical for breaking poverty cycles. Educate Girls represents Indian civil society excellence — demonstrating NGO effectiveness addressing systemic educational inequities. The award validated India's domestic social sector leadership. Other 2025 laureates: Shaahina Ali (Maldives, marine conservation) and Fr. Flaviano Villanueva (Philippines, human rights priest). Ceremony: November 7, 2025, Manila; Prize: US$50,000. Previous Indian individual winners: Vinoba Bhave (1958, first-ever Magsaysay laureate), Mother Teresa (1962). Educate Girls's award represented Indian NGO sector's growing international recognition and legitimacy.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23091,"question_text":"Booker Prize 2025 winner David Szalay made history as the first author of which nationality to win the Booker?","option_a":"Hungarian-British","option_b":"Romanian-Canadian","option_c":"Polish-American","option_d":"Czech-French","correct_answer":"A","explanation":"David Szalay won the Booker Prize 2025 for 'Flesh' — historic achievement as the FIRST HUNGARIAN-BRITISH author to win the Booker Prize. Born in Montreal, Canada to Hungarian father, raised in London, he writes sophisticated English-language fiction about European masculinity, class, and existential themes. 'Flesh' follows Magyar man István from adolescence through old age — exploring desire, ambition, mortality. The sparse narrative employs white space strategically (noted by prize chair Roddy Doyle as distinctive feature). Prize: £50,000 (shared between author/publisher). Ceremony: November 10, 2025, London. Szalay's Booker win coincided with Nobel Literature 2025 awarding László Krasznahorkai (Hungarian) — making 2025 a transformative year for Hungarian literature globally. Hungarian authors demonstrated international literary excellence transcending geographic boundaries. Szalay's British upbringing, Canadian birth, and literary success in English exemplifies contemporary globalised literature transcending national categories. His win validated philosophical, minimalist fiction addressing universal human experiences.","folder":"AP_HC","topic":"International_Current_Affairs"},
    {"id":23092,"question_text":"The Sakharov Prize 2024 (European Parliament's human rights prize) was awarded to which two figures together — both leading opposition to Venezuela's Maduro government?","option_a":"Juan Guaidó and Leopoldo López","option_b":"María Corina Machado and Edmundo González","option_c":"Henrique Capriles and Antonio Ledezma","option_d":"Lilian Tintori and Antonieta Mendoza","correct_answer":"B","explanation":"Sakharov Prize 2024 (awarded December 2024): María Corina Machado AND Edmundo González Urrutia (jointly) — primary leaders of Venezuela's democratic opposition against Nicolás Maduro's authoritarian regime. Machado won 2024 opposition primary with overwhelming support but was barred from candidacy through legal disqualifications — exemplifying authoritarian suppression tactics. González emerged as consensus opposition candidate for July 2024 presidential election, widely seen as winning popular vote despite Maduro's disputed victory claims. Machado subsequently won the Nobel Peace Prize 2025 (October) — individual honour complementing the joint Sakharov recognition. The dual awards (Sakharov 2024, Nobel 2025) validated Venezuelan opposition's democratic legitimacy against international democratic standards. Sakharov Prize 2025: Iranian women human-rights defenders of 'Woman, Life, Freedom' movement. Venezuela's award recognition demonstrated how international honours document democratic struggles against authoritarianism.","folder":"AP_HC","topic":"International_Current_Affairs"},
]


def seed():
    if USE_POSTGRES:
        import psycopg2
        conn = psycopg2.connect(DATABASE_URL)
        conn.autocommit = False
        cur = conn.cursor()
        delete_sql = "DELETE FROM questions WHERE id >= %s AND id <= %s"
        insert_sql = """INSERT INTO questions
            (id, question_text, option_a, option_b, option_c, option_d,
             correct_answer, explanation, topic, folder, difficulty)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
            ON CONFLICT (id) DO NOTHING"""
    else:
        conn = sqlite3.connect(
            os.path.join(os.path.dirname(__file__), "database.db")
        )
        cur = conn.cursor()
        delete_sql = "DELETE FROM questions WHERE id >= ? AND id <= ?"
        insert_sql = """INSERT OR IGNORE INTO questions
            (id, question_text, option_a, option_b, option_c, option_d,
             correct_answer, explanation, topic, folder, difficulty)
            VALUES (?,?,?,?,?,?,?,?,?,?,?)"""

    cur.execute(delete_sql, (23001, 23092))

    for q in AWARDS_MCQS:
        cur.execute(insert_sql, (
            q["id"], q["question_text"],
            q["option_a"], q["option_b"], q["option_c"], q["option_d"],
            q["correct_answer"], q["explanation"],
            q["topic"], q["folder"], "M"
        ))

    conn.commit()
    conn.close()
    print(f"[seed_awards_mcq] {len(AWARDS_MCQS)} Awards 2025-2026 MCQs seeded (IDs 23001-23092).")


if __name__ == "__main__":
    seed()
